[package]
name = "oathrs"
version = "0.1.0"
edition = "2021"

# The kernel library: identity, gate, eval, gen, verify, analyses. Pure
# computation — no threads, no process, no filesystem — so it cross-compiles to
# wasm32 unchanged. The `prove` module (drives z3 as a subprocess) is behind a
# default feature and excluded from wasm builds.
[lib]
name = "oathrs"
path = "src/lib.rs"

[[bin]]
name = "oathrs"
path = "src/main.rs"

[features]
default = ["prove"]
prove = []

[dependencies]
sha2 = "0.10"
# Arbitrary-precision integers: `Int` is ℤ (SPEC §3). The Go kernel uses
# math/big; this is the analogous crate. Default features only (no rand/serde),
# so it cross-compiles to wasm unchanged.
num-bigint = "0.4"

[profile.release]
opt-level = 2
//! Oath conformance kernel — library crate.
//!
//! Everything here is pure computation (collections, strings, sha2) and builds
//! for wasm32 unchanged. The `prove` module (SMT via a z3 subprocess) is
//! native-only, behind the default `prove` feature, and is the sole part that
//! depends on `std::process`. See DIVERGENCES.md for the host assumptions the
//! wasm port surfaced (notably the evaluator's host-stack recursion, §3.1).

pub mod analyze;
pub mod campaign;
pub mod check;
pub mod crypto;
pub mod elaborate;
pub mod eval;
pub mod gen;
pub mod hash;
pub mod ir;
pub mod sexpr;
pub mod value;
pub mod verify;

#[cfg(feature = "prove")]
pub mod prove;
//! SHA-256, lowercase hex (SPEC §1).

use sha2::{Digest, Sha256};

/// Raw SHA-256 digest (32 bytes). Shared by object identity (§1) and the
/// `hmac-sha256` primitive (§1.3), which is RFC 2104 over this compression.
pub fn sha256(bytes: &[u8]) -> [u8; 32] {
    let mut h = Sha256::new();
    h.update(bytes);
    let digest = h.finalize();
    let mut out = [0u8; 32];
    out.copy_from_slice(&digest);
    out
}

pub fn sha256_hex(bytes: &[u8]) -> String {
    let digest = sha256(bytes);
    let mut s = String::with_capacity(64);
    for b in digest.iter() {
        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
        s.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
    }
    s
}

