    if 'envelope' in o: print('  envelope:',json.dumps(o['envelope']))
    if 'envelope_b64' in o: print('  envelope_b64:',o['envelope_b64'])
    if 'journal_line_b64' in o: print('  journal_line:',repr(base64.b64decode(o['journal_line_b64'])))
"

