//! Base64 in the dialect SPEC §8.6.3 pins for `envelope_b64`.
//!
//! "base64" alone admits several spellings of one byte string, and this member
//! is compared and re-encoded (§8.2.1), so the dialect is nailed down: RFC 4648
//! §4 **standard** alphabet (`+` and `/`), padding **required**, no line breaks,
//! no whitespace anywhere, no URL-safe substitutions. §8.6.3 adds a round-trip
//! obligation on top: a verifier MUST reject the member unless re-encoding the
//! decoded octets reproduces it exactly, which is what rules out the spellings
//! a permissive decoder would otherwise let through (non-zero tail bits being
//! the classic one — `Zg==` and `Zh==` both decode to `f`).
//!
//! `decode_canonical` is therefore the function every verifier path should call;
//! `decode` alone is the plain dialect check and is exposed only because the
//! round-trip rule is stated as a separate obligation.
//!
//! Note this is also the encoding the §10.1 fixture channel uses for every
//! octet string, so the same functions read the vectors.

const ALPHABET: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

/// RFC 4648 §4 encode: standard alphabet, padded to a multiple of four, no line
/// breaks. This is the only spelling §8.6.3 admits.
pub fn encode(bytes: &[u8]) -> String {
    let mut out = String::with_capacity((bytes.len() + 2) / 3 * 4);
    let mut chunks = bytes.chunks_exact(3);
    for c in &mut chunks {
        let n = ((c[0] as u32) << 16) | ((c[1] as u32) << 8) | c[2] as u32;
        for shift in [18, 12, 6, 0] {
            out.push(ALPHABET[((n >> shift) & 0x3f) as usize] as char);
        }
    }
    let rest = chunks.remainder();
    match rest.len() {
        0 => {}
        1 => {
            let n = (rest[0] as u32) << 16;
            out.push(ALPHABET[((n >> 18) & 0x3f) as usize] as char);
