/// four, padding present and only in the final quantum, and no whitespace
/// tolerated anywhere (a leading space, a trailing newline, or an internal line
/// break are all errors — §8.6.3 says "no whitespace anywhere", and a decoder
/// that skips it accepts several stored spellings of one statement).
///
/// This does NOT enforce the round-trip rule; see `decode_canonical`.
pub fn decode(s: &str) -> Result<Vec<u8>, String> {
    let b = s.as_bytes();
    if b.len() % 4 != 0 {
        return Err(format!(
            "base64 length {} is not a multiple of 4 (padding is required)",
            b.len()
        ));
    }
    // Padding is legal only as the last one or two characters of the input.
    let pad = b.iter().rev().take_while(|&&c| c == b'=').count();
    if pad > 2 {
