                    format!(
                        "base64 contains URL-safe character '{}'; the standard alphabet is pinned",
                        c as char
                    )
                } else {
                    format!("base64 contains non-alphabet byte 0x{:02x}", c)
                }
            })?;
            acc = (acc << 6) | v;
            n += 1;
        }
