/// The verifier's obligation from §8.6.3 in full: decode under the pinned
/// dialect AND require that re-encoding the decoded octets reproduces the input
/// exactly, "so alternate spellings that decode to the same octets from
/// different stored bytes are refused".
pub fn decode_canonical(s: &str) -> Result<Vec<u8>, String> {
    let octets = decode(s)?;
    let re = encode(&octets);
    if re != s {
        return Err(format!(
            "base64 is not the canonical spelling of its own octets (re-encodes to {:?})",
            re
        ));
    }
    Ok(octets)
}

