            assert_eq!(encode(plain.as_bytes()), *b64, "encode {:?}", plain);
            assert_eq!(decode_canonical(b64).unwrap(), plain.as_bytes(), "decode {:?}", b64);
        }
    }

    #[test]
    fn all_byte_values_round_trip() {
        let all: Vec<u8> = (0..=255u8).collect();
        for n in 0..all.len() {
            let s = encode(&all[..n]);
            assert_eq!(decode_canonical(&s).unwrap(), &all[..n]);
        }
    }

