    fn unpadded_is_rejected() {
        // §8.6.3: padding is required.
        assert!(decode("Zg").is_err());
        assert!(decode("Zm9vYg").is_err());
    }

    #[test]
    fn whitespace_anywhere_is_rejected() {
        assert!(decode(" Zm9v").is_err());
        assert!(decode("Zm9v ").is_err());
        assert!(decode("Zm9v\nYmFy").is_err());
        assert!(decode("Zm9\tv").is_err());
    }

    #[test]
    fn url_safe_alphabet_is_rejected() {
        // 0xfb 0xff encodes as "+/8=" in the standard alphabet; the URL-safe
        // spelling "-_8=" decodes to the same octets and MUST still be refused.
        assert_eq!(encode(&[0xfb, 0xff]), "+/8=");
        assert!(decode("-_8=").is_err());
    }

    #[test]
    fn non_canonical_tail_bits_are_rejected() {
        // "Zg==" and "Zh==" both decode to "f" under a permissive decoder; only
        // the first is the canonical spelling, and §8.6.3's round-trip rule is
        // what refuses the second.
        assert_eq!(decode("Zh==").unwrap(), b"f");
        assert!(decode_canonical("Zh==").is_err());
        assert!(decode_canonical("Zg==").is_ok());
    }

    #[test]
    fn misplaced_padding_is_rejected() {
        assert!(decode("Zg==Zg==").is_err());
        assert!(decode("=Zg=").is_err());
    }
}

