//! Ed25519 under the convention SPEC §8.6.4a pins.
//!
//! §8.6.4a exists because "a valid Ed25519 signature" is not a single predicate:
//! the choices are observable between implementations, so a signature one kernel
//! accepts another may reject. What is pinned here:
//!
//!   * RFC 8032 §5.1.7 verification with the **cofactorless** equation
//!     `[S]B = R + [k]A` (NOT the cofactored `[8][S]B = [8]R + [8][k]A`);
//!   * `S` MUST be canonical, i.e. strictly less than the group order `L`.
//!     A non-canonical `S` admits a second signature over the same message under
//!     the same key, which contradicts an envelope being *the author's statement*;
//!   * `R` and `A` MUST be canonical point encodings;
//!   * a small-order `A` MUST be **rejected** (§8.6.4a's amendment: this was a
//!     MAY, which made journal validity non-portable — two conforming verifiers
//!     could disagree about whether one journal is well-formed).
//!
//! Signing is deterministic (RFC 8032), so signatures are a function of the
//! private key and the message; the §10.1 vectors pin a seed rather than a nonce,
//! and `secret_from_seed` + `sign` reproduce them.
//!
//! Written from RFC 8032 directly. Field arithmetic is `num_bigint` modular
//! arithmetic over p = 2^255 - 19 rather than a hand-rolled limb
//! representation: verification does a few thousand modular multiplications, the
//! kernel verifies a handful of signatures, and the readable version is the one
//! whose correctness can be argued from the RFC. `num-bigint` is already a
//! dependency (`Int` is ℤ, SPEC §3), so this adds none, and everything here is
//! pure computation, so the wasm surface is unchanged.

use crate::hash::sha512;
use num_bigint::BigUint;

/// A point in extended twisted-Edwards coordinates (X : Y : Z : T) with
/// x = X/Z, y = Y/Z and T = XY/Z (RFC 8032 §5.1.4).
#[derive(Clone, Debug)]
struct Point {
    x: BigUint,
    y: BigUint,
    z: BigUint,
    t: BigUint,
}

/// The curve constants, built once per operation. Holding them in a struct keeps
/// `p` out of the inner loops without a lazy static.
struct Curve {
    p: BigUint,
    /// 2*d, the only form of d the addition formula needs.
    d2: BigUint,
    /// The prime order of the base point's subgroup, L = 2^252 + 27742...493.
    l: BigUint,
    /// 2^((p-1)/4), the square root of -1 used in x-recovery.
    sqrt_m1: BigUint,
    /// The base point B.
    b: Point,
}

fn big(dec: &str) -> BigUint {
    BigUint::parse_bytes(dec.as_bytes(), 10).expect("constant parses")
}

impl Curve {
    fn new() -> Curve {
        // p = 2^255 - 19
        let p = (BigUint::from(1u8) << 255u32) - BigUint::from(19u8);
        // d = -121665 / 121666 mod p
        let num = &p - BigUint::from(121665u32);
        let den = BigUint::from(121666u32);
        let d = (num * mod_inv(&den, &p)) % &p;
        let d2 = (d.clone() + d) % &p;
        let l = (BigUint::from(1u8) << 252u32)
            + big("27742317777372353535851937790883648493");
        // sqrt(-1) = 2^((p-1)/4) mod p, valid because p ≡ 5 (mod 8).
        let sqrt_m1 = BigUint::from(2u8).modpow(&((&p - BigUint::from(1u8)) >> 2u32), &p);
        // B = (x, 4/5) with x the even-signed root; RFC 8032 §5.1.
        let by = (BigUint::from(4u8) * mod_inv(&BigUint::from(5u8), &p)) % &p;
        let mut c = Curve {
            p: p.clone(),
            d2,
            l,
            sqrt_m1: sqrt_m1.clone(),
            b: Point {
                x: BigUint::from(0u8),
                y: BigUint::from(1u8),
                z: BigUint::from(1u8),
                t: BigUint::from(0u8),
            },
        };
        let bx = c.recover_x(&by, 0).expect("base point y has a root");
        c.b = c.affine(&bx, &by);
        c
    }

    fn add_m(&self, a: &BigUint, b: &BigUint) -> BigUint {
        (a + b) % &self.p
    }
    fn sub_m(&self, a: &BigUint, b: &BigUint) -> BigUint {
        // Both operands are reduced, so one borrow of p suffices.
        (a + &self.p - b) % &self.p
    }
    fn mul_m(&self, a: &BigUint, b: &BigUint) -> BigUint {
        (a * b) % &self.p
    }

    fn affine(&self, x: &BigUint, y: &BigUint) -> Point {
        Point {
            x: x.clone(),
            y: y.clone(),
            z: BigUint::from(1u8),
            t: self.mul_m(x, y),
        }
    }

    fn identity(&self) -> Point {
        Point {
            x: BigUint::from(0u8),
            y: BigUint::from(1u8),
            z: BigUint::from(1u8),
            t: BigUint::from(0u8),
        }
    }

    /// RFC 8032 §5.1.4 unified addition on the extended coordinates. Unified
    /// means it is also correct for P == Q, so doubling needs no special case.
    fn add(&self, p1: &Point, p2: &Point) -> Point {
        let a = self.mul_m(&self.sub_m(&p1.y, &p1.x), &self.sub_m(&p2.y, &p2.x));
        let b = self.mul_m(&self.add_m(&p1.y, &p1.x), &self.add_m(&p2.y, &p2.x));
        let c = self.mul_m(&self.mul_m(&self.d2, &p1.t), &p2.t);
        let d = self.mul_m(&self.add_m(&p1.z, &p1.z), &p2.z);
        let e = self.sub_m(&b, &a);
        let f = self.sub_m(&d, &c);
        let g = self.add_m(&d, &c);
        let h = self.add_m(&b, &a);
        Point {
            x: self.mul_m(&e, &f),
            y: self.mul_m(&g, &h),
            t: self.mul_m(&e, &h),
            z: self.mul_m(&f, &g),
        }
    }

    /// [k]P by MSB-first double-and-add. Not constant time; nothing here handles
    /// a secret scalar except `sign`, which the kernel uses only to reproduce
    /// fixture signatures from a fixture seed, so there is no secret to leak.
    fn mul(&self, k: &BigUint, p: &Point) -> Point {
        let mut acc = self.identity();
        let bits = k.bits();
        for i in (0..bits).rev() {
            acc = self.add(&acc, &acc);
            if ((k >> i) & BigUint::from(1u8)) == BigUint::from(1u8) {
                acc = self.add(&acc, p);
            }
        }
        acc
    }

    /// Projective equality: X1/Z1 == X2/Z2 and Y1/Z1 == Y2/Z2, cross-multiplied
    /// so no inversion is needed.
    fn eq(&self, a: &Point, b: &Point) -> bool {
        self.mul_m(&a.x, &b.z) == self.mul_m(&b.x, &a.z)
            && self.mul_m(&a.y, &b.z) == self.mul_m(&b.y, &a.z)
    }

    /// Recover x from y and the sign bit (RFC 8032 §5.1.3). `None` when
    /// (y² - 1)/(d y² + 1) is not a square, i.e. y is not on the curve, and also
    /// for the one non-canonical case the RFC calls out: x == 0 with the sign bit
    /// set, which is a second encoding of a point that already has one.
    fn recover_x(&self, y: &BigUint, sign: u8) -> Option<BigUint> {
        let y2 = self.mul_m(y, y);
        let u = self.sub_m(&y2, &BigUint::from(1u8));
        // d y² + 1, expressed through d2 to avoid carrying d as well.
        let d = self.mul_m(&self.d2, &mod_inv(&BigUint::from(2u8), &self.p));
        let v = self.add_m(&self.mul_m(&d, &y2), &BigUint::from(1u8));
        let uv = self.mul_m(&u, &mod_inv(&v, &self.p));
        if uv == BigUint::from(0u8) {
            // x² == 0, so x == 0; the sign bit must then be clear.
            return if sign == 0 { Some(BigUint::from(0u8)) } else { None };
        }
        // p ≡ 5 (mod 8), so a candidate root is uv^((p+3)/8) and, when that
        // squares to -uv, the true root is that times sqrt(-1).
        let exp = (&self.p + BigUint::from(3u8)) >> 3u32;
        let mut x = uv.modpow(&exp, &self.p);
        if self.mul_m(&x, &x) != uv {
            x = self.mul_m(&x, &self.sqrt_m1);
        }
        if self.mul_m(&x, &x) != uv {
            return None; // not a square: y is not the ordinate of any point
        }
        if (x.clone() % BigUint::from(2u8)) != BigUint::from(sign as u32) {
            x = self.sub_m(&BigUint::from(0u8), &x);
        }
        Some(x)
    }

    /// Decode a 32-byte point encoding, insisting it is CANONICAL (§8.6.4a).
    /// Canonical means: the 255-bit little-endian ordinate is strictly less than
    /// p (so `y + p` is not a second encoding of one point), the ordinate is
    /// actually on the curve, and x == 0 does not carry a set sign bit.
    fn decode_point(&self, enc: &[u8]) -> Result<Point, String> {
        if enc.len() != 32 {
            return Err(format!("point encoding is {} bytes, want 32", enc.len()));
        }
        let sign = enc[31] >> 7;
        let mut ybytes = enc.to_vec();
        ybytes[31] &= 0x7f;
        let y = BigUint::from_bytes_le(&ybytes);
        if y >= self.p {
            return Err("non-canonical point encoding: ordinate is not reduced mod p".into());
        }
        let x = self
            .recover_x(&y, sign)
            .ok_or_else(|| "non-canonical point encoding: no such curve point".to_string())?;
        Ok(self.affine(&x, &y))
    }

    fn encode_point(&self, p: &Point) -> [u8; 32] {
        let zi = mod_inv(&p.z, &self.p);
        let x = self.mul_m(&p.x, &zi);
        let y = self.mul_m(&p.y, &zi);
        let mut out = [0u8; 32];
        let yb = y.to_bytes_le();
        out[..yb.len()].copy_from_slice(&yb);
        if (x % BigUint::from(2u8)) == BigUint::from(1u8) {
            out[31] |= 0x80;
        }
        out
    }

    /// A point has small order iff [8]P is the identity: the curve's torsion
    /// subgroup has order 8, so every point of order dividing 8 — the identity
    /// included — is annihilated by multiplication by the cofactor.
    fn is_small_order(&self, p: &Point) -> bool {
        let p2 = self.add(p, p);
        let p4 = self.add(&p2, &p2);
        let p8 = self.add(&p4, &p4);
        self.eq(&p8, &self.identity())
    }
}

/// Modular inverse by Fermat: a^(p-2) mod p. p is prime, and `a` is never zero
/// on any path here (z is never zero for a point reachable by the group law, and
/// the denominators in x-recovery are nonzero on the curve).
fn mod_inv(a: &BigUint, p: &BigUint) -> BigUint {
    a.modpow(&(p - BigUint::from(2u8)), p)
}

/// A 32-byte Ed25519 public key.
pub type PublicKey = [u8; 32];

/// The expanded secret: the clamped scalar `a` and the prefix used for the
/// deterministic nonce (RFC 8032 §5.1.5).
pub struct Secret {
    scalar: BigUint,
    prefix: [u8; 32],
    pub public: PublicKey,
}

/// Expand a 32-byte seed into the signing key, per RFC 8032 §5.1.5. §10.1's
/// vectors carry `seed_b64`, so this is how a fixture's key is derived.
pub fn secret_from_seed(seed: &[u8]) -> Result<Secret, String> {
    if seed.len() != 32 {
        return Err(format!("seed is {} bytes, want 32", seed.len()));
    }
    let h = sha512(seed);
    let mut s = [0u8; 32];
    s.copy_from_slice(&h[..32]);
    // Clamping: clear the low three bits, clear the top bit, set bit 254.
    s[0] &= 248;
    s[31] &= 127;
    s[31] |= 64;
    let scalar = BigUint::from_bytes_le(&s);
    let mut prefix = [0u8; 32];
    prefix.copy_from_slice(&h[32..]);
    let c = Curve::new();
    let a = c.mul(&scalar, &c.b);
    Ok(Secret { scalar, prefix, public: c.encode_point(&a) })
}

/// Deterministic RFC 8032 signing. Present so the kernel can produce envelope
/// signatures and so the §10.1 seed can be checked against the fixture's
/// recorded `author_pubkey` and `author_sig` — a fixture that pins a seed is
/// only usable by an implementation that can re-derive both.
pub fn sign(secret: &Secret, msg: &[u8]) -> [u8; 64] {
    let c = Curve::new();
    let mut buf = Vec::with_capacity(32 + msg.len());
    buf.extend_from_slice(&secret.prefix);
    buf.extend_from_slice(msg);
    let r = BigUint::from_bytes_le(&sha512(&buf)) % &c.l;
    let rp = c.mul(&r, &c.b);
    let renc = c.encode_point(&rp);

    let mut buf = Vec::with_capacity(64 + msg.len());
    buf.extend_from_slice(&renc);
    buf.extend_from_slice(&secret.public);
    buf.extend_from_slice(msg);
    let k = BigUint::from_bytes_le(&sha512(&buf)) % &c.l;
    let s = (r + k * &secret.scalar) % &c.l;

    let mut out = [0u8; 64];
    out[..32].copy_from_slice(&renc);
    let sb = s.to_bytes_le();
    out[32..32 + sb.len()].copy_from_slice(&sb);
    out
}

/// Verify under the pinned convention (SPEC §8.6.4a). Returns the reason on
/// failure rather than a bare bool, because every clause here is a distinct
/// normative rule and a caller reporting "signature invalid" for all of them
/// makes a conformance divergence undiagnosable.
pub fn verify(pubkey: &[u8], sig: &[u8], msg: &[u8]) -> Result<(), String> {
    if pubkey.len() != 32 {
        return Err(format!("public key is {} bytes, want 32", pubkey.len()));
    }
    if sig.len() != 64 {
        return Err(format!("signature is {} bytes, want 64", sig.len()));
    }
    let c = Curve::new();

    // Canonical S: strictly less than L. §8.6.4a — a non-canonical S is a
    // second signature over the same message under the same key.
    let s = BigUint::from_bytes_le(&sig[32..]);
    if s >= c.l {
        return Err("non-canonical signature: S is not less than the group order L".into());
    }

    let a = c.decode_point(pubkey).map_err(|e| format!("public key: {}", e))?;
    // §8.6.4a: a small-order A MUST be rejected. Signatures under such a key
    // verify for parties who do not hold it, so it makes no authorship claim.
    if c.is_small_order(&a) {
        return Err("small-order public key: it can make no authorship claim".into());
    }
    let r = c.decode_point(&sig[..32]).map_err(|e| format!("signature R: {}", e))?;

    let mut buf = Vec::with_capacity(64 + msg.len());
    buf.extend_from_slice(&sig[..32]);
    buf.extend_from_slice(pubkey);
    buf.extend_from_slice(msg);
    let k = BigUint::from_bytes_le(&sha512(&buf)) % &c.l;

    // Cofactorless: [S]B == R + [k]A, checked projectively.
    let lhs = c.mul(&s, &c.b);
    let rhs = c.add(&r, &c.mul(&k, &a));
    if c.eq(&lhs, &rhs) {
        Ok(())
    } else {
        Err("signature does not verify: [S]B != R + [k]A".into())
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn unhex(s: &str) -> Vec<u8> {
        s.as_bytes()
            .chunks(2)
            .map(|p| u8::from_str_radix(std::str::from_utf8(p).unwrap(), 16).unwrap())
            .collect()
    }
    fn hex(b: &[u8]) -> String {
        let mut s = String::new();
        for x in b {
            s.push(char::from_digit((x >> 4) as u32, 16).unwrap());
            s.push(char::from_digit((x & 0xf) as u32, 16).unwrap());
        }
        s
    }

    // RFC 8032 §7.1 TEST 1: empty message.
    #[test]
    fn rfc8032_test1() {
        let seed = unhex("9d61b19deffd5a60ba844af492ec2cc44449c5697b326919703bac031cae7f60");
        let pk = unhex("d75a980182b10ab7d54bfed3c964073a0ee172f3daa62325af021a68f707511a");
        let sig = unhex(
            "e5564300c360ac729086e2cc806e828a84877f1eb8e5d974d873e065224901555fb8821590a33bacc61e39701cf9b46bd25bf5f0595bbe24655141438e7a100b",
        );
        let s = secret_from_seed(&seed).unwrap();
        assert_eq!(hex(&s.public), hex(&pk));
        assert_eq!(hex(&sign(&s, b"")), hex(&sig));
        assert!(verify(&pk, &sig, b"").is_ok());
    }

    // RFC 8032 §7.1 TEST 2: one-byte message.
    #[test]
    fn rfc8032_test2() {
        let seed = unhex("4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb");
        let pk = unhex("3d4017c3e843895a92b70aa74d1b7ebc9c982ccf2ec4968cc0cd55f12af4660c");
        let sig = unhex(
            "92a009a9f0d4cab8720e820b5f642540a2b27b5416503f8fb3762223ebdb69da085ac1e43e15996e458f3613d0f11d8c387b2eaeb4302aeeb00d291612bb0c00",
        );
        let s = secret_from_seed(&seed).unwrap();
        assert_eq!(hex(&s.public), hex(&pk));
        assert_eq!(hex(&sign(&s, &[0x72])), hex(&sig));
        assert!(verify(&pk, &sig, &[0x72]).is_ok());
    }

    // RFC 8032 §7.1 TEST 3: two-byte message.
    #[test]
    fn rfc8032_test3() {
        let seed = unhex("c5aa8df43f9f837bedb7442f31dcb7b166d38535076f094b85ce3a2e0b4458f7");
        let pk = unhex("fc51cd8e6218a1a38da47ed00230f0580816ed13ba3303ac5deb911548908025");
        let sig = unhex(
            "6291d657deec24024827e69c3abe01a30ce548a284743a445e3680d7db5ac3ac18ff9b538d16f290ae67f760984dc6594a7c15e9716ed28dc027beceea1ec40a",
        );
        let s = secret_from_seed(&seed).unwrap();
        assert_eq!(hex(&s.public), hex(&pk));
        assert_eq!(hex(&sign(&s, &[0xaf, 0x82])), hex(&sig));
        assert!(verify(&pk, &sig, &[0xaf, 0x82]).is_ok());
    }

    // RFC 8032 §7.1 TEST 1024: a long message, which exercises the SHA-512
    // multi-block path.
    #[test]
    fn rfc8032_test1024() {
        let seed = unhex("f5e5767cf153319517630f226876b86c8160cc583bc013744c6bf255f5cc0ee5");
        let pk = unhex("278117fc144c72340f67d0f2316e8386ceffbf2b2428c9c51fef7c597f1d426e");
        let msg = unhex("");
        let sig = unhex("0aab4c900501b3e24d7cdf4663326a3a87df5e4843b2cbdb67cbf6e460fec350aa5371b1508f9f4528ecea23c436d94b5e8fcd4f681e30a6ac00a9704a188a03");
        let s = secret_from_seed(&seed).unwrap();
        assert_eq!(hex(&s.public), hex(&pk));
        assert_eq!(hex(&sign(&s, &msg)), hex(&sig));
        assert!(verify(&pk, &sig, &msg).is_ok());
    }

    #[test]
    fn tampered_message_fails() {
        let seed = unhex("4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb");
        let s = secret_from_seed(&seed).unwrap();
        let sig = sign(&s, b"hello");
        assert!(verify(&s.public, &sig, b"hello").is_ok());
        assert!(verify(&s.public, &sig, b"hellp").is_err());
        assert!(verify(&s.public, &sig, b"hell").is_err());
    }

    // §8.6.4a: S MUST be canonical. S + L verifies under the cofactorless
    // equation just as S does — the group only sees S mod L — so this must be
    // refused on the ENCODING, not by the curve equation.
    #[test]
    fn non_canonical_s_is_rejected() {
        let seed = unhex("4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb");
        let s = secret_from_seed(&seed).unwrap();
        let sig = sign(&s, b"malleable");
        assert!(verify(&s.public, &sig, b"malleable").is_ok());

        let c = Curve::new();
        let sval = BigUint::from_bytes_le(&sig[32..]);
        let bumped = sval + &c.l;
        let bb = bumped.to_bytes_le();
        assert!(bb.len() <= 32, "S + L still fits in 32 bytes for this vector");
        let mut mal = sig;
        mal[32..].copy_from_slice(&[0u8; 32]);
        mal[32..32 + bb.len()].copy_from_slice(&bb);
        let e = verify(&s.public, &mal, b"malleable").unwrap_err();
        assert!(e.contains("group order L"), "{}", e);
    }

    // §8.6.4a: a small-order A MUST be rejected. The all-zero encoding is the
    // ordinate y = 0, whose x is a square root of -1: a point of order 4, and
    // the canonical small-order encoding a fixture can carry without curve
    // arithmetic.
    #[test]
    fn small_order_key_is_rejected() {
        let c = Curve::new();
        let zero = [0u8; 32];
        let p = c.decode_point(&zero).expect("y=0 decodes to a curve point");
        assert!(c.is_small_order(&p));
        let e = verify(&zero, &[0u8; 64], b"anything").unwrap_err();
        assert!(e.contains("small-order"), "{}", e);

        // The identity itself, and the order-2 point, are small order too.
        let ident = c.encode_point(&c.identity());
        assert_eq!(ident[0], 1);
        assert!(c.is_small_order(&c.decode_point(&ident).unwrap()));
        assert!(verify(&ident, &[0u8; 64], b"x").unwrap_err().contains("small-order"));
    }

    // A genuine key is NOT small order, so the rule costs nothing legitimate.
    #[test]
    fn real_key_is_not_small_order() {
        let c = Curve::new();
        let seed = unhex("4ccd089b28ff96da9db6c346ec114e0f5b8a319f35aba624da8cf6ed4fb8a6fb");
        let s = secret_from_seed(&seed).unwrap();
        assert!(!c.is_small_order(&c.decode_point(&s.public).unwrap()));
    }

    // Canonical point encodings: an ordinate >= p is a second spelling and MUST
    // be refused. y = p (i.e. 19 with the high limb set) is the smallest such.
    #[test]
    fn unreduced_ordinate_is_rejected() {
        let c = Curve::new();
        let mut enc = [0u8; 32];
        let pb = c.p.to_bytes_le();
        enc[..pb.len()].copy_from_slice(&pb);
        let e = c.decode_point(&enc).unwrap_err();
        assert!(e.contains("not reduced"), "{}", e);
    }

    // An ordinate that is on no curve point must be refused rather than
    // silently mapped to something.
    #[test]
    fn off_curve_ordinate_is_rejected() {
        let c = Curve::new();
        // Search for a y with no x; roughly half of all y qualify.
        let mut found = false;
        for y in 2u32..64 {
            let mut enc = [0u8; 32];
            enc[..4].copy_from_slice(&y.to_le_bytes());
            if c.decode_point(&enc).is_err() {
                found = true;
                break;
            }
        }
        assert!(found, "some small ordinate is off the curve");
    }

    // x == 0 with the sign bit SET is a non-canonical spelling of a point that
    // already has an encoding with the bit clear.
    #[test]
    fn zero_x_with_sign_bit_is_rejected() {
        let c = Curve::new();
        // y = 1 gives x = 0 (the identity).
        let mut enc = [0u8; 32];
        enc[0] = 1;
        assert!(c.decode_point(&enc).is_ok());
        enc[31] |= 0x80;
        assert!(c.decode_point(&enc).is_err());
    }

    // Base-point sanity: [L]B is the identity, and B itself is not small order.
    #[test]
    fn base_point_has_order_l() {
        let c = Curve::new();
        assert!(c.eq(&c.mul(&c.l, &c.b), &c.identity()));
        assert!(!c.is_small_order(&c.b));
    }
}

