//! A minimal JSON reader plus the canonical string escaping SPEC §8.2.1 pins.
//!
//! Two consumers, both in the metadata layer (never identity):
//!
//!   * the fixture channel (§10) — `prove/outcomes.json`, `envelope/vectors.jsonl`;
//!   * journal entries (§8.2.1), where the ESCAPING is normative because `chain`,
//!     entry signatures (§8.4) and entry digests (§8.2.2) are all computed over
//!     these bytes.
//!
//! `Num` keeps the literal source text rather than parsing to a machine number.
//! That is load-bearing, not laziness: §8.6.1's `parent_rev` is explicitly
//! unbounded and the §10.1 vectors carry one past 2^64 as a JSON NUMBER, so a
//! reader that widened it to `f64` — the default in most JSON libraries — would
//! silently round a valid historical statement into a different one. Keeping the
//! digits also lets `seq` be re-emitted byte-identically.

/// A parsed JSON value. `Obj` keeps members as an ordered `Vec` so a reader can
/// see the order they appeared in and detect duplicates — both of which §8.2.1
/// makes errors, and neither of which a map representation can express.
#[derive(Debug, Clone, PartialEq)]
pub enum Json {
    Null,
    Bool(bool),
    Num(String),
    Str(String),
    Arr(Vec<Json>),
    Obj(Vec<(String, Json)>),
}

impl Json {
    pub fn get(&self, key: &str) -> Option<&Json> {
        match self {
            Json::Obj(kvs) => kvs.iter().find(|(k, _)| k == key).map(|(_, v)| v),
            _ => None,
        }
    }
    pub fn arr(&self) -> &[Json] {
        match self {
            Json::Arr(v) => v,
            _ => &[],
        }
    }
    pub fn members(&self) -> &[(String, Json)] {
        match self {
            Json::Obj(kvs) => kvs,
            _ => &[],
        }
    }
    pub fn str(&self) -> Option<&str> {
        match self {
            Json::Str(s) => Some(s),
            _ => None,
        }
    }
    /// The literal digits of a number, unwidened.
    pub fn num(&self) -> Option<&str> {
        match self {
            Json::Num(n) => Some(n),
            _ => None,
        }
    }
    pub fn usize(&self) -> Option<usize> {
        match self {
            Json::Num(n) => n.parse().ok(),
            _ => None,
        }
    }
    pub fn is_true(&self) -> bool {
        matches!(self, Json::Bool(true))
    }
}

