//! The publication envelope — SPEC §8.6.1 (canonical encoding), §8.6.2 (the
//! name revision) and the store-side preconditions of §8.6.4.
//!
//! An envelope is the AUTHOR's statement, signed before submission and persisted
//! verbatim, so authorship is checkable without trusting the store (§8.6). It
//! covers only what the author controls — the name, the artifact, and the
//! transition — and never store-derived verdicts, which an author cannot predict.
//!
//! Everything in this module is byte-significant. The encoded octets are what a
//! signature is computed over, so a single differing byte does not produce an
//! error: it makes every signature this kernel produces unverifiable by another
//! and vice versa, with the signature staying *correct* and ceasing to *verify*.
//! That is why the parser is as strict as the encoder and why `parse_canonical`
//! — parse, re-encode, require byte equality — is the entry point every verifier
//! path uses.

use num_bigint::BigUint;

/// The format tag of this envelope version. It is INSIDE the signed bytes, so a
/// signature made under one format version can never be read under another.
pub const FORMAT_TAG: &str = "oath-publish/1";

/// The six `key=value` lines, in the normative order. Order is part of the
/// encoding: a reordered envelope is a different byte string and MUST be refused.
const KEYS: [&str; 6] = ["op", "name", "artifact", "parent", "parent_rev", "author"];

/// A parsed publication envelope.
///
/// `op` is not a field: `put` is the only operation this version defines, so a
/// parsed envelope always means `put` and the encoder always emits it. Making it
/// a field would invite representing an envelope this version cannot express.
///
/// `parent` is `Option<String>` with `None` standing for the `-` sentinel, which
/// makes §8.6.1's "`parent` is `-` if and only if `parent_rev` is 0" a check on
/// one pair of values rather than a string comparison.
///
/// `parent_rev` is a `BigUint` because §8.6.1 says it is **unbounded**: an
/// implementation MUST NOT impose a machine-word limit, since doing so would
/// declare a valid historical statement malformed once a name had been repointed
/// often enough.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Envelope {
    pub name: String,
    pub artifact: String,
    pub parent: Option<String>,
    pub parent_rev: BigUint,
    pub author: String,
}

fn is_lower_hex64(s: &str) -> bool {
    s.len() == 64 && s.bytes().all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c))
}

/// §8.6.1's value rule: "every value is free of LF, CR, and any character below
/// `0x20` or equal to `0x7F`". Applied per Unicode scalar, since the octets are
/// UTF-8 and the forbidden set is entirely ASCII.
fn bad_char(s: &str) -> Option<char> {
    s.chars().find(|&c| (c as u32) < 0x20 || c == '\u{7f}')
}

impl Envelope {
    /// The `parent` field as it appears in the encoding: the sentinel or the hex.
    pub fn parent_str(&self) -> &str {
        match &self.parent {
            Some(h) => h,
            None => "-",
        }
    }

    /// Every §8.6.1 rejection rule, in one place, so the encoder and the parser
    /// cannot drift apart. §8.6.1 requires rejection "on both encoding and
    /// verification".
    pub fn validate(&self) -> Result<(), String> {
        // `name` is non-empty and otherwise unconstrained beyond the character
        // rule. In particular it MAY contain `=`.
        if self.name.is_empty() {
            return Err("name is empty".into());
        }
        if !is_lower_hex64(&self.artifact) {
            return Err(format!(
                "artifact {:?} is not 64 lowercase hex characters (uppercase MUST be rejected: \
                 the encoding is compared as bytes, so ABAB… and abab… would be two statements \
                 about one artifact)",
                self.artifact
            ));
        }
        match &self.parent {
            Some(h) if !is_lower_hex64(h) => {
                return Err(format!("parent {:?} is neither 64 lowercase hex nor `-`", h));
            }
            _ => {}
        }
        if !is_lower_hex64(&self.author) {
            return Err(format!("author {:?} is not 64 lowercase hex characters", self.author));
        }
        // `parent` is `-` if and only if `parent_rev` is 0. A first publication
        // has both or neither; allowing disagreement would let one envelope
        // describe two different states.
        let rev_zero = self.parent_rev == BigUint::from(0u8);
        match (&self.parent, rev_zero) {
            (None, false) => {
                return Err(format!(
                    "parent is the `-` sentinel but parent_rev is {}; a first publication has both \
                     or neither",
                    self.parent_rev
                ))
            }
            (Some(_), true) => {
                return Err(
                    "parent is a hash but parent_rev is 0; a first publication has both or neither"
                        .into(),
                )
            }
            _ => {}
        }
        // The value rule. Reachable here only for `name` in practice — the other
        // values are hex, `-`, or decimal digits — but checked for all of them,
        // because §8.6.1 states it of "every value" and the encoder is the side
        // where it bites (a value containing LF would inject a line and the
        // encoding would stop being uniquely decodable).
        for (key, val) in [
            ("name", self.name.as_str()),
            ("artifact", self.artifact.as_str()),
            ("parent", self.parent_str()),
            ("author", self.author.as_str()),
        ] {
            if let Some(c) = bad_char(val) {
                return Err(format!(
                    "{} contains forbidden character U+{:04X}: values are free of LF, CR, and any \
                     character below 0x20 or equal to 0x7F",
                    key, c as u32
                ));
            }
        }
        Ok(())
    }

    /// Canonical encoding (§8.6.1): a version line then exactly six `key=value`
    /// lines in the order above, each terminated by one LF. There is no other
    /// whitespace, no trailing content, and no optional field.
    ///
    /// `parent_rev` is rendered as canonical decimal — no leading zeros, no sign,
    /// no spaces — which `BigUint`'s decimal rendering gives directly.
    pub fn encode(&self) -> Result<Vec<u8>, String> {
        self.validate()?;
        let mut s = String::new();
        s.push_str(FORMAT_TAG);
        s.push('\n');
        s.push_str("op=put\n");
        s.push_str("name=");
        s.push_str(&self.name);
        s.push('\n');
        s.push_str("artifact=");
        s.push_str(&self.artifact);
        s.push('\n');
        s.push_str("parent=");
        s.push_str(self.parent_str());
        s.push('\n');
        s.push_str("parent_rev=");
        s.push_str(&self.parent_rev.to_str_radix(10));
        s.push('\n');
        s.push_str("author=");
        s.push_str(&self.author);
        s.push('\n');
        Ok(s.into_bytes())
    }
}

/// Strict parse (§8.6.1). Unknown keys, missing keys, duplicated keys, reordered
/// keys, a missing trailing LF, and trailing bytes are all errors.
///
/// Duplicates and reordering fall out of the positional key check: the key on
/// line *i* must be exactly `KEYS[i-1]`, so a repeated `op` line is reported as
/// "expected name".
pub fn parse(octets: &[u8]) -> Result<Envelope, String> {
    // The octets are UTF-8 (§8.6.1). Invalid UTF-8 is refused: a `name` that is
    // not UTF-8 is not a name in this encoding, and it could never be compared
    // against a journal entry's `name`, which lives in JSON.
    let text = std::str::from_utf8(octets).map_err(|e| format!("envelope is not UTF-8: {}", e))?;

    // Framing first: the last octet must be the single terminating LF, and
    // stripping it must leave exactly seven LF-separated lines. A missing
    // trailing LF is an error, and so is any trailing byte after it.
    if !text.ends_with('\n') {
        return Err("envelope does not end with LF: framing is part of the encoding, and a \
                    truncated envelope is not a shorter valid one"
            .into());
    }
    let body = &text[..text.len() - 1];
    let lines: Vec<&str> = body.split('\n').collect();
    if lines.len() != 7 {
        return Err(format!(
            "envelope has {} lines, want 7 (a version line and exactly six key=value lines)",
            lines.len()
        ));
    }

    // The format tag is a MUST. A different tag is not a newer envelope to be
    // interpreted — it is an envelope this version cannot verify.
    if lines[0] != FORMAT_TAG {
        return Err(format!(
            "format tag is {:?}, want {:?}: a signature made under one format version cannot be \
             read under another",
            lines[0], FORMAT_TAG
        ));
    }

    let mut vals: Vec<&str> = Vec::with_capacity(6);
    for (i, key) in KEYS.iter().enumerate() {
        let line = lines[i + 1];
        // Each line splits at its FIRST `=`, so `name=a=b` names `a=b` and is
        // not ambiguous.
        let eq = line
            .find('=')
            .ok_or_else(|| format!("line {} has no `=`: expected {}=<value>", i + 2, key))?;
        if &line[..eq] != *key {
            return Err(format!(
                "line {} has key {:?}, want {:?} (key order is part of the encoding)",
                i + 2,
                &line[..eq],
                key
            ));
        }
        vals.push(&line[eq + 1..]);
    }

    // `op` is `put`, the only operation defined in this version.
    if vals[0] != "put" {
        return Err(format!("op is {:?}, want \"put\"", vals[0]));
    }

    let parent = if vals[3] == "-" { None } else { Some(vals[3].to_string()) };

    // `parent_rev` is a non-negative integer in canonical decimal: no leading
    // zeros, no sign, no spaces. `03` and `+3` MUST be rejected, since they would
    // be distinct bytes for one revision.
    let rev_text = vals[4];
    if rev_text.is_empty() || !rev_text.bytes().all(|c| c.is_ascii_digit()) {
        return Err(format!(
            "parent_rev {:?} is not a non-negative decimal integer (no sign, no spaces)",
            rev_text
        ));
    }
    if rev_text.len() > 1 && rev_text.starts_with('0') {
        return Err(format!(
            "parent_rev {:?} has a leading zero; {:?} and {:?} would be different bytes for one \
             revision",
            rev_text, rev_text, rev_text.trim_start_matches('0')
        ));
    }
    let parent_rev = BigUint::parse_bytes(rev_text.as_bytes(), 10)
        .ok_or_else(|| format!("parent_rev {:?} does not parse", rev_text))?;

    let env = Envelope {
        name: vals[1].to_string(),
        artifact: vals[2].to_string(),
        parent,
        parent_rev,
        author: vals[5].to_string(),
    };
    env.validate()?;
    Ok(env)
}

/// Parse AND verify that re-encoding the parsed value reproduces the input bytes
/// exactly (§8.6.1). This is the function every verification path should call:
/// "canonical encoding without canonical parsing would protect identity at
/// creation and discard it at verification".
pub fn parse_canonical(octets: &[u8]) -> Result<Envelope, String> {
    let env = parse(octets)?;
    let re = env.encode()?;
    if re != octets {
        return Err("envelope does not re-encode to its input bytes".into());
    }
    Ok(env)
}

// ---------------------------------------------------------------------------
// The store-side preconditions of §8.6.4.
// ---------------------------------------------------------------------------

/// What the store currently believes about a name: its binding, and its revision
/// (§8.6.2). `bound` is `None` for a name that was never published, which §8.6.2
/// says is the only unresolvable case, since names in this version are only ever
/// repointed and never deleted.
#[derive(Debug, Clone)]
pub struct NameState {
    pub name: String,
    pub bound: Option<String>,
    pub rev: BigUint,
}

impl NameState {
    /// The state of a name that has never been published: `parent=-`,
    /// `parent_rev=0`.
    pub fn unpublished(name: &str) -> NameState {
        NameState { name: name.to_string(), bound: None, rev: BigUint::from(0u8) }
    }
}

/// A submitted signed publication as the store sees it.
///
/// `authenticated_principal` is deliberately separate from anything inside the
/// octets: §8.6.4 requires the signing key to be the authenticated principal and
/// NOT the key the envelope names, because "verifying against the envelope's own
/// `author` would always succeed, so a caller could submit any valid statement
/// made by anyone".
///
/// `recomputed_artifact` is the hash the store computed from the submitted
/// content, never a hash the client supplied.
#[derive(Debug, Clone)]
pub struct PublishRequest {
    pub octets: Vec<u8>,
    pub author_sig: String,
    pub authenticated_principal: String,
    pub recomputed_artifact: String,
}

/// The three store-side MUSTs of §8.6.4, checked **before** the name moves, plus
/// the signature itself — a store that checked the preconditions but not the
/// signature would be enforcing a compare-and-swap on an unauthenticated
/// statement.
///
/// A statement failing any check MUST NOT move the name. The object itself MAY
/// still be stored (storage is idempotent under content addressing and an
/// unreferenced object is inert), and a failed attempt SHOULD be journalled;
/// both of those are the caller's business, which is why this function only
/// decides.
pub fn check_publication(
    state: &NameState,
    req: &PublishRequest,
) -> Result<Envelope, String> {
    let env = parse_canonical(&req.octets)?;

    if env.name != state.name {
        return Err(format!(
            "envelope names {:?} but the request is against {:?}",
            env.name, state.name
        ));
    }

    // (1) the signing key is the authenticated principal, not the key the
    // envelope names.
    if !is_lower_hex64(&req.authenticated_principal) {
        return Err("authenticated principal is not 64 lowercase hex characters".into());
    }
    if env.author != req.authenticated_principal {
        return Err(format!(
            "envelope author {} is not the authenticated principal {}: verifying against the \
             envelope's own author would always succeed",
            env.author, req.authenticated_principal
        ));
    }
    let key = unhex(&req.authenticated_principal)?;
    let sig = unhex(&req.author_sig)?;
    crate::ed25519::verify(&key, &sig, &req.octets)
        .map_err(|e| format!("author signature: {}", e))?;

    // (2) recompute the artifact hash from the submitted content and require it
    // to equal the signed `artifact`.
    if req.recomputed_artifact != env.artifact {
        return Err(format!(
            "recomputed artifact {} does not equal the signed artifact {}",
            req.recomputed_artifact, env.artifact
        ));
    }

    // (3) the signed `parent` and `parent_rev` are the name's current values.
    let bound = state.bound.as_deref().unwrap_or("-");
    if env.parent_str() != bound {
        return Err(format!(
            "signed parent {} is not the name's current binding {}",
            env.parent_str(),
            bound
        ));
    }
    if env.parent_rev != state.rev {
        return Err(format!(
            "signed parent_rev {} is not the name's current revision {}: a hash can return to an \
             earlier value, a revision cannot",
            env.parent_rev, state.rev
        ));
    }
    Ok(env)
}

/// Decode lowercase hex. Uppercase is refused everywhere in §8.6: these fields
/// are compared as bytes.
pub fn unhex(s: &str) -> Result<Vec<u8>, String> {
    if s.len() % 2 != 0 {
        return Err(format!("hex string has odd length {}", s.len()));
    }
    let b = s.as_bytes();
    let mut out = Vec::with_capacity(b.len() / 2);
    for pair in b.chunks(2) {
        let hi = lower_hex_val(pair[0])?;
        let lo = lower_hex_val(pair[1])?;
        out.push((hi << 4) | lo);
    }
    Ok(out)
}

fn lower_hex_val(c: u8) -> Result<u8, String> {
    match c {
        b'0'..=b'9' => Ok(c - b'0'),
        b'a'..=b'f' => Ok(c - b'a' + 10),
        _ => Err(format!("{:?} is not a lowercase hex digit", c as char)),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn env() -> Envelope {
        Envelope {
            name: "double".into(),
            artifact: "5".repeat(64),
            parent: Some("6".repeat(64)),
            parent_rev: BigUint::from(7u8),
            author: "7".repeat(64),
        }
    }

    #[test]
    fn canonical_shape() {
        let bytes = env().encode().unwrap();
        let text = String::from_utf8(bytes.clone()).unwrap();
        assert!(text.starts_with("oath-publish/1\nop=put\nname=double\n"));
        assert!(text.ends_with('\n'));
        assert_eq!(text.lines().count(), 7);
        assert!(!text.contains('\r'));
        assert_eq!(parse_canonical(&bytes).unwrap(), env());
    }

    #[test]
    fn first_publication_uses_the_sentinel() {
        let e = Envelope { parent: None, parent_rev: BigUint::from(0u8), ..env() };
        let bytes = e.encode().unwrap();
        assert!(String::from_utf8_lossy(&bytes).contains("\nparent=-\nparent_rev=0\n"));
        assert_eq!(parse_canonical(&bytes).unwrap(), e);
    }

    #[test]
    fn name_may_contain_equals_and_splits_at_the_first() {
        let e = Envelope { name: "a=b".into(), parent: None, parent_rev: BigUint::from(0u8), ..env() };
        let bytes = e.encode().unwrap();
        assert_eq!(parse_canonical(&bytes).unwrap().name, "a=b");
    }

    #[test]
    fn name_may_be_non_ascii_and_stays_literal_utf8() {
        let e = Envelope {
            name: "café/λ-fold".into(),
            parent: None,
            parent_rev: BigUint::from(0u8),
            ..env()
        };
        let bytes = e.encode().unwrap();
        assert!(bytes.windows(2).any(|w| w == [0xc3, 0xa9]), "é is literal UTF-8");
        assert_eq!(parse_canonical(&bytes).unwrap(), e);
    }

    #[test]
    fn parent_rev_is_unbounded() {
        let big = BigUint::parse_bytes(b"340282366920938463463374607431768211457", 10).unwrap();
        let e = Envelope { parent_rev: big.clone(), ..env() };
        let bytes = e.encode().unwrap();
        assert!(String::from_utf8_lossy(&bytes)
            .contains("parent_rev=340282366920938463463374607431768211457"));
        assert_eq!(parse_canonical(&bytes).unwrap().parent_rev, big);
    }

    // ---- rejection rules (§8.6.1) ------------------------------------------

    fn octets(s: &str) -> Vec<u8> {
        s.as_bytes().to_vec()
    }
    const OK: &str = "oath-publish/1\nop=put\nname=n\nartifact=abababababababababababababababababababababababababababababababab\nparent=-\nparent_rev=0\nauthor=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n";

    #[test]
    fn the_baseline_is_accepted() {
        assert!(parse_canonical(&octets(OK)).is_ok());
    }

    #[test]
    fn wrong_format_tag_is_rejected() {
        let bad = OK.replace("oath-publish/1", "oath-publish/2");
        assert!(parse(&octets(&bad)).unwrap_err().contains("format tag"));
        // Also a tag that merely has extra content.
        let bad = OK.replace("oath-publish/1\n", "oath-publish/1 \n");
        assert!(parse(&octets(&bad)).is_err());
    }

    #[test]
    fn uppercase_hex_is_rejected() {
        let bad = OK.replace("artifact=abab", "artifact=ABAB");
        assert!(parse(&octets(&bad)).unwrap_err().contains("lowercase"));
        let bad = OK.replace("author=aaaa", "author=AAAA");
        assert!(parse(&octets(&bad)).is_err());
    }

    #[test]
    fn short_or_nonhex_artifact_is_rejected() {
        assert!(parse(&octets(&OK.replace("artifact=abab", "artifact=ab"))).is_err());
        assert!(parse(&octets(&OK.replace("artifact=abab", "artifact=zbab"))).is_err());
        assert!(parse(&octets(&OK.replace("artifact=abab", "artifact="))).is_err());
    }

    #[test]
    fn non_canonical_revision_is_rejected() {
        let base = OK
            .replace("parent=-", "parent=cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd");
        assert!(parse(&octets(&base.replace("parent_rev=0", "parent_rev=01"))).is_err());
        assert!(parse(&octets(&base.replace("parent_rev=0", "parent_rev=+3"))).is_err());
        assert!(parse(&octets(&base.replace("parent_rev=0", "parent_rev=-3"))).is_err());
        assert!(parse(&octets(&base.replace("parent_rev=0", "parent_rev= 3"))).is_err());
        assert!(parse(&octets(&base.replace("parent_rev=0", "parent_rev=3 "))).is_err());
        assert!(parse(&octets(&base.replace("parent_rev=0", "parent_rev="))).is_err());
        // ...and the canonical spelling of the same revision is accepted.
        assert!(parse_canonical(&octets(&base.replace("parent_rev=0", "parent_rev=3"))).is_ok());
    }

    #[test]
    fn sentinel_and_revision_must_agree_both_ways() {
        assert!(parse(&octets(&OK.replace("parent_rev=0", "parent_rev=2")))
            .unwrap_err()
            .contains("both or neither"));
        let bad = OK
            .replace("parent=-", "parent=cdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcdcd");
        assert!(parse(&octets(&bad)).unwrap_err().contains("both or neither"));
    }

    #[test]
    fn op_must_be_put() {
        assert!(parse(&octets(&OK.replace("op=put", "op=delete"))).is_err());
        // A trailing space is a different value, not the same operation.
        assert!(parse(&octets(&OK.replace("op=put", "op=put "))).is_err());
    }

    #[test]
    fn empty_name_is_rejected() {
        assert!(parse(&octets(&OK.replace("name=n", "name="))).unwrap_err().contains("empty"));
    }

    #[test]
    fn reordered_keys_are_rejected() {
        let bad = "oath-publish/1\nname=n\nop=put\nartifact=abababababababababababababababababababababababababababababababab\nparent=-\nparent_rev=0\nauthor=aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\n";
        assert!(parse(&octets(bad)).unwrap_err().contains("key order"));
    }

    #[test]
    fn missing_duplicated_and_extra_keys_are_rejected() {
        // missing `parent`
        let bad = OK.replace("parent=-\n", "");
        assert!(parse(&octets(&bad)).is_err());
        // duplicated `op`
        let bad = OK.replace("op=put\n", "op=put\nop=put\n");
        assert!(parse(&octets(&bad)).is_err());
        // an unknown extra field
        let bad = format!("{}extra=1\n", OK);
        assert!(parse(&octets(&bad)).is_err());
    }

    #[test]
    fn framing_errors_are_rejected() {
        // missing trailing LF
        assert!(parse(&octets(OK.trim_end_matches('\n'))).unwrap_err().contains("end with LF"));
        // trailing bytes after the final LF
        assert!(parse(&octets(&format!("{}x", OK))).is_err());
        // a blank line at the end is an eighth line
        assert!(parse(&octets(&format!("{}\n", OK))).is_err());
        // CRLF line endings are not LF line endings
        assert!(parse(&octets(&OK.replace('\n', "\r\n"))).is_err());
    }

    #[test]
    fn lf_in_a_value_presents_as_a_line_count_error() {
        // §8.6.1 notes the value rule is reachable only on the ENCODING side: an
        // injected LF in stored octets presents as a line-count error, never as
        // "a value contained an LF".
        let bad = OK.replace("name=n", "name=a\nb");
        let e = parse(&octets(&bad)).unwrap_err();
        assert!(e.contains("8 lines"), "{}", e);
    }

    #[test]
    fn control_characters_in_a_value_are_rejected_on_the_parse_side_too() {
        // CR, DEL and other C0 characters do NOT break line framing, so unlike
        // LF they ARE reachable from the parse side. No fixture covers them.
        for c in ['\r', '\u{7f}', '\u{0}', '\u{1}', '\u{1f}'] {
            let bad = OK.replace("name=n", &format!("name=a{}b", c));
            assert!(parse(&octets(&bad)).is_err(), "U+{:04X} must be refused", c as u32);
        }
    }

    #[test]
    fn the_encoder_refuses_what_the_parser_refuses() {
        // §8.6.1: reject "on both encoding and verification".
        for bad in [
            Envelope { name: String::new(), ..env() },
            Envelope { name: "a\nb".into(), ..env() },
            Envelope { name: "a\rb".into(), ..env() },
            Envelope { name: "a\u{7f}b".into(), ..env() },
            Envelope { artifact: "A".repeat(64), ..env() },
            Envelope { artifact: "ab".into(), ..env() },
            Envelope { author: "F".repeat(64), ..env() },
            Envelope { parent: None, ..env() },
            Envelope { parent_rev: BigUint::from(0u8), ..env() },
        ] {
            assert!(bad.encode().is_err(), "{:?} must not encode", bad);
        }
    }

    #[test]
    fn invalid_utf8_is_rejected() {
        let mut bytes = octets(OK);
        // Splice an invalid continuation byte into the name.
        let pos = bytes.windows(7).position(|w| w == b"name=n\n").unwrap() + 5;
        bytes[pos] = 0xff;
        assert!(parse(&bytes).unwrap_err().contains("UTF-8"));
    }

    // ---- store-side preconditions (§8.6.4) --------------------------------

    #[test]
    fn store_checks_reject_a_non_principal_signer() {
        let seed = [7u8; 32];
        let secret = crate::ed25519::secret_from_seed(&seed).unwrap();
        let mut author = String::new();
        for b in secret.public.iter() {
            author.push(char::from_digit((b >> 4) as u32, 16).unwrap());
            author.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
        }
        let e = Envelope { author: author.clone(), ..env() };
        let octets = e.encode().unwrap();
        let sig = crate::ed25519::sign(&secret, &octets);
        let mut sig_hex = String::new();
        for b in sig.iter() {
            sig_hex.push(char::from_digit((b >> 4) as u32, 16).unwrap());
            sig_hex.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
        }
        let state = NameState {
            name: "double".into(),
            bound: Some("6".repeat(64)),
            rev: BigUint::from(7u8),
        };
        let req = PublishRequest {
            octets: octets.clone(),
            author_sig: sig_hex.clone(),
            authenticated_principal: author.clone(),
            recomputed_artifact: "5".repeat(64),
        };
        assert!(check_publication(&state, &req).is_ok());

        // A different authenticated principal must fail even though the envelope
        // is a perfectly valid statement by its own author.
        let other = crate::ed25519::secret_from_seed(&[9u8; 32]).unwrap();
        let mut other_hex = String::new();
        for b in other.public.iter() {
            other_hex.push(char::from_digit((b >> 4) as u32, 16).unwrap());
            other_hex.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
        }
        let bad = PublishRequest { authenticated_principal: other_hex, ..req.clone() };
        assert!(check_publication(&state, &bad).is_err());

        // A recomputed artifact that disagrees with the signed one.
        let bad = PublishRequest { recomputed_artifact: "9".repeat(64), ..req.clone() };
        assert!(check_publication(&state, &bad).unwrap_err().contains("recomputed artifact"));

        // A stale parent.
        let moved = NameState { bound: Some("7".repeat(64)), ..state.clone() };
        assert!(check_publication(&moved, &req).unwrap_err().contains("current binding"));

        // A stale revision though the parent hash matches (the ABA case).
        let aba = NameState { rev: BigUint::from(9u8), ..state.clone() };
        assert!(check_publication(&aba, &req).unwrap_err().contains("current revision"));

        // A tampered signature.
        let mut broken = sig_hex.clone();
        broken.replace_range(0..1, if sig_hex.starts_with('0') { "1" } else { "0" });
        let bad = PublishRequest { author_sig: broken, ..req.clone() };
        assert!(check_publication(&state, &bad).is_err());

        // A first publication against an unpublished name.
        let first = Envelope {
            name: "fresh".into(),
            parent: None,
            parent_rev: BigUint::from(0u8),
            author: author.clone(),
            ..env()
        };
        let foctets = first.encode().unwrap();
        let fsig = crate::ed25519::sign(&secret, &foctets);
        let mut fsig_hex = String::new();
        for b in fsig.iter() {
            fsig_hex.push(char::from_digit((b >> 4) as u32, 16).unwrap());
            fsig_hex.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
        }
        let freq = PublishRequest {
            octets: foctets,
            author_sig: fsig_hex,
            authenticated_principal: author,
            recomputed_artifact: "5".repeat(64),
        };
        assert!(check_publication(&NameState::unpublished("fresh"), &freq).is_ok());
        // ...but not against a name that already exists.
        assert!(check_publication(
            &NameState { name: "fresh".into(), bound: Some("1".repeat(64)), rev: BigUint::from(1u8) },
            &freq
        )
        .is_err());
    }
}

