//! The journal — SPEC §8, §8.2.1 (canonical entry encoding), §8.2.2 (publication
//! identity), §8.4 (entry signatures), and the entry-side obligations of §8.6.
//!
//! Everything here is metadata: no journal field is ever part of definition
//! identity (§9). It is nonetheless BYTE-significant, for a reason §8.2.1 states
//! plainly — `chain`, entry signatures and entry digests are all computed over
//! "the entry's compact JSON", so two implementations that order members or
//! escape strings differently compute different chains and different signatures
//! for the same logical entry, and each then rejects the other's journal
//! wholesale.
//!
//! Two rules earn their emphasis:
//!
//!   * reading is STRICT — parse, re-encode canonically, require byte equality.
//!     §8.2.1: "Canonical writing with lenient reading protects nothing", and a
//!     tool MUST NOT parse a non-canonical line, normalize it, and verify the
//!     normalized form, because that verifies a statement other than the one the
//!     journal contains.
//!   * the record separator (a single LF between entries) is FRAMING and is not
//!     part of entry identity: it enters neither the chain, nor the entry
//!     signature, nor the entry digest.

use crate::envelope::{self, Envelope, NameState};
use crate::hash::sha256_hex;
use crate::json::{self, Json};
use num_bigint::BigUint;

/// The normative member order of §8.2.1. This is not a formatting preference:
/// "An undefined order is a byte-level fork waiting for a second implementation."
pub const MEMBER_ORDER: [&str; 20] = [
    "seq",
    "time",
    "author",
    "verifier",
    "name",
    "kind",
    "status",
    "hash",
    "prev",
    "error",
    "guarantee",
    "termination",
    "context",
    "pubkey",
    "sig",
    "envelope_b64",
    "author_pubkey",
    "author_sig",
    "name_transition",
    "chain",
];

/// The members that are emitted even when empty (§8.2.1). Note `verifier` is in
/// this list: it was missing from the first draft of §8.2.1, and because the
/// conformance vectors carry `"verifier":""` a strict reader implementing the
/// prose literally refused the fixture's own journal line.
pub const ALWAYS_PRESENT: [&str; 6] = ["seq", "time", "author", "verifier", "name", "status"];

/// One journal entry.
///
/// `seq` is a `BigUint` rather than a machine integer for the same reason
/// §8.6.1's `parent_rev` is: it is a count over an append-only log with no stated
/// bound, and a width limit would declare a long-lived journal malformed. It also
/// makes the canonical rendering exact — `BigUint`'s decimal form has no leading
/// zeros, no sign and no exponent, so `1e3`, `+1` and `01` all fail the
/// re-encode-to-input check for free.
#[derive(Debug, Clone, PartialEq, Eq, Default)]
pub struct Entry {
    pub seq: BigUint,
    pub time: String,
    pub author: String,
    pub verifier: String,
    pub name: String,
    pub kind: String,
    pub status: String,
    pub hash: String,
    pub prev: String,
    pub error: String,
    pub guarantee: String,
    pub termination: String,
    pub context: String,
    pub pubkey: String,
    pub sig: String,
    pub envelope_b64: String,
    pub author_pubkey: String,
    pub author_sig: String,
    pub name_transition: String,
    pub chain: String,
}

impl Entry {
    fn field(&self, key: &str) -> &str {
        match key {
            "time" => &self.time,
            "author" => &self.author,
            "verifier" => &self.verifier,
            "name" => &self.name,
            "kind" => &self.kind,
            "status" => &self.status,
            "hash" => &self.hash,
            "prev" => &self.prev,
            "error" => &self.error,
            "guarantee" => &self.guarantee,
            "termination" => &self.termination,
            "context" => &self.context,
            "pubkey" => &self.pubkey,
            "sig" => &self.sig,
            "envelope_b64" => &self.envelope_b64,
            "author_pubkey" => &self.author_pubkey,
            "author_sig" => &self.author_sig,
            "name_transition" => &self.name_transition,
            "chain" => &self.chain,
            _ => unreachable!("unknown journal member {}", key),
        }
    }

    fn field_mut(&mut self, key: &str) -> &mut String {
        match key {
            "time" => &mut self.time,
            "author" => &mut self.author,
            "verifier" => &mut self.verifier,
            "name" => &mut self.name,
            "kind" => &mut self.kind,
            "status" => &mut self.status,
            "hash" => &mut self.hash,
            "prev" => &mut self.prev,
            "error" => &mut self.error,
            "guarantee" => &mut self.guarantee,
            "termination" => &mut self.termination,
            "context" => &mut self.context,
            "pubkey" => &mut self.pubkey,
            "sig" => &mut self.sig,
            "envelope_b64" => &mut self.envelope_b64,
            "author_pubkey" => &mut self.author_pubkey,
            "author_sig" => &mut self.author_sig,
            "name_transition" => &mut self.name_transition,
            "chain" => &mut self.chain,
            _ => unreachable!("unknown journal member {}", key),
        }
    }

    /// Canonical entry encoding (§8.2.1): a compact JSON object whose members
    /// appear in exactly the normative order, with empty members omitted except
    /// the always-present six, and strings escaped minimally.
    ///
    /// The result is the canonical LINE — the object bytes ALONE, with no record
    /// separator.
    pub fn encode(&self) -> Vec<u8> {
        let mut out = String::from("{");
        let mut first = true;
        for key in MEMBER_ORDER {
            let always = ALWAYS_PRESENT.contains(&key);
            let rendered = if key == "seq" {
                // "Members whose value is empty (or zero, for `seq`) are
                // omitted" — but `seq` is always present, so the zero clause only
                // ever matters for a hypothetical future reader.
                if self.seq == BigUint::from(0u8) && !always {
                    continue;
                }
                self.seq.to_str_radix(10)
            } else {
                let v = self.field(key);
                if v.is_empty() && !always {
                    continue;
                }
                json::escape(v)
            };
            if !first {
                out.push(',');
            }
            first = false;
            out.push_str(&json::escape(key));
            out.push(':');
            out.push_str(&rendered);
        }
        out.push('}');
        out.into_bytes()
    }

    /// The entry digest (§8.2.2): SHA-256 over the exact canonical entry line,
    /// lowercase hex — the object bytes only, excluding the record separator.
    ///
    /// The identity of one PUBLICATION, not of the content it publishes: "An
    /// artifact hash identifies CONTENT, not a publication of that content", and a
    /// reader that selects the first or last matching entry for a hash is guessing
    /// which was meant.
    pub fn digest(&self) -> String {
        sha256_hex(&self.encode())
    }

    /// Whether this entry's digest also fixes its POSITION (§8.2.2). It does only
    /// where the entry is CHAINED, because `chain` is part of the line and two
    /// entries identical in content at different positions then have different
    /// chains. An unchained entry duplicated verbatim elsewhere has the same
    /// digest, so an implementation relying on positional uniqueness MUST require
    /// the entry to be chained.
    pub fn digest_fixes_position(&self) -> bool {
        !self.chain.is_empty()
    }

    /// The §8.4 signed content: the entry's compact JSON with the store-assigned
    /// fields `seq`, `time`, `verifier` and `chain`, and `sig` itself, all set
    /// empty/omitted — so the signature covers exactly the authored fields
    /// (including `pubkey`), independent of where the entry lands in the log.
    pub fn signed_content(&self) -> Vec<u8> {
        let mut e = self.clone();
        e.seq = BigUint::from(0u8);
        e.time.clear();
        e.verifier.clear();
        e.sig.clear();
        e.chain.clear();
        e.encode()
    }

    /// `chain = SHA-256(anchor + "\n" + entry-bytes)` in lowercase hex, where
    /// entry-bytes is the entry's compact JSON with `chain` empty (§8).
    pub fn chain_over(&self, anchor: &str) -> String {
        let mut e = self.clone();
        e.chain.clear();
        let mut buf = Vec::new();
        buf.extend_from_slice(anchor.as_bytes());
        buf.push(b'\n');
        buf.extend_from_slice(&e.encode());
        sha256_hex(&buf)
    }
}

/// Parse a journal line. Unknown members and duplicated members are errors here;
/// reordering, added whitespace and non-canonical escaping are caught by
/// `read_strict`'s byte comparison.
pub fn parse(line: &[u8]) -> Result<Entry, String> {
    let doc = json::parse(line)?;
    let members = match &doc {
        Json::Obj(kvs) => kvs,
        _ => return Err("journal line is not a JSON object".into()),
    };
    let mut e = Entry::default();
    let mut seen: Vec<&str> = Vec::with_capacity(members.len());
    for (k, v) in members {
        if !MEMBER_ORDER.contains(&k.as_str()) {
            return Err(format!("unknown journal member {:?}", k));
        }
        if seen.contains(&k.as_str()) {
            return Err(format!("duplicated journal member {:?}", k));
        }
        seen.push(k.as_str());
        if k == "seq" {
            let digits = v
                .num()
                .ok_or_else(|| "seq is not a JSON number".to_string())?;
            if digits.is_empty() || !digits.bytes().all(|c| c.is_ascii_digit()) {
                return Err(format!("seq {:?} is not a non-negative decimal integer", digits));
            }
            if digits.len() > 1 && digits.starts_with('0') {
                return Err(format!("seq {:?} has a leading zero", digits));
            }
            e.seq = BigUint::parse_bytes(digits.as_bytes(), 10)
                .ok_or_else(|| format!("seq {:?} does not parse", digits))?;
        } else {
            let s = v
                .str()
                .ok_or_else(|| format!("journal member {:?} is not a string", k))?;
            *e.field_mut(k) = s.to_string();
        }
    }
    for key in ALWAYS_PRESENT {
        if !seen.contains(&key) {
            return Err(format!(
                "journal member {:?} is absent; it is always present even when empty",
                key
            ));
        }
    }
    Ok(e)
}

/// Read a line STRICTLY (§8.2.1): parse it, re-encode it canonically, and reject
/// unless the result is byte-identical to the stored line. Unknown members,
/// duplicated members, reordered members, added whitespace, and trailing content
/// after the object are all errors.
pub fn read_strict(line: &[u8]) -> Result<Entry, String> {
    let e = parse(line)?;
    let re = e.encode();
    if re != line {
        return Err(format!(
            "journal line is not canonical; it re-encodes to {} bytes that differ from the {} \
             stored (§8.2.1 forbids normalizing and then verifying the normalized form)",
            re.len(),
            line.len()
        ));
    }
    Ok(e)
}

/// §8.4: a verifier MUST, for every entry whose `pubkey` or `sig` is non-empty,
/// reject the journal unless `pubkey` is a well-formed 32-byte key and `sig` is a
/// valid Ed25519 signature under it over the signed content. One field without
/// the other is a forged attribution and MUST be rejected, not treated as
/// unattributed.
pub fn verify_entry_signature(e: &Entry) -> Result<(), String> {
    if e.pubkey.is_empty() && e.sig.is_empty() {
        return Ok(());
    }
    if e.pubkey.is_empty() || e.sig.is_empty() {
        return Err("entry carries one of pubkey/sig without the other: a forged attribution".into());
    }
    let key = envelope::unhex(&e.pubkey).map_err(|x| format!("pubkey: {}", x))?;
    if key.len() != 32 {
        return Err(format!("pubkey is {} bytes, want 32", key.len()));
    }
    let sig = envelope::unhex(&e.sig).map_err(|x| format!("sig: {}", x))?;
    crate::ed25519::verify(&key, &sig, &e.signed_content()).map_err(|x| format!("entry signature: {}", x))
}

/// §8.6.4: for every entry where ANY of `envelope_b64`, `author_pubkey`,
/// `author_sig` is non-empty, all five clauses must hold.
///
/// The member is `envelope_b64`, not `envelope`. §8.6.4 previously named the
/// latter, and that reading FAILS OPEN: an implementation checking presence
/// member-by-member finds `envelope` always absent, concludes no obligation
/// applies, and accepts every forged publication while passing every vector. The
/// presence test below is therefore over the three real member names.
///
/// Returns the parsed envelope when one was present, so a caller does not parse
/// twice.
pub fn verify_publication(e: &Entry) -> Result<Option<Envelope>, String> {
    let present = [&e.envelope_b64, &e.author_pubkey, &e.author_sig];
    if present.iter().all(|s| s.is_empty()) {
        // "Entries with none of the three fields impose no obligation and are
        // conformant."
        return Ok(None);
    }
    // (1) all three are present. Any one alone attests to nothing.
    if present.iter().any(|s| s.is_empty()) {
        return Err(
            "publication fields are partial: envelope_b64, author_pubkey and author_sig are \
             all-or-none, and any one alone attests to nothing"
                .into(),
        );
    }
    // (2) `envelope_b64` decodes under the pinned dialect, and the decoded octets
    // parse under §8.6.1 and re-encode to themselves.
    let octets = crate::b64::decode_canonical(&e.envelope_b64)
        .map_err(|x| format!("envelope_b64: {}", x))?;
    let env = envelope::parse_canonical(&octets)?;

    // (3) the envelope's `author` equals `author_pubkey`.
    if env.author != e.author_pubkey {
        return Err(format!(
            "envelope author {} does not equal author_pubkey {}",
            env.author, e.author_pubkey
        ));
    }

    // (4) `author_sig` is valid under `author_pubkey` over the octets DECODED
    // FROM `envelope_b64` — not over a re-encoding of the parsed envelope, and
    // not over the base64 text.
    let key = envelope::unhex(&e.author_pubkey).map_err(|x| format!("author_pubkey: {}", x))?;
    if key.len() != 32 {
        return Err(format!("author_pubkey is {} bytes, want 32", key.len()));
    }
    let sig = envelope::unhex(&e.author_sig).map_err(|x| format!("author_sig: {}", x))?;
    crate::ed25519::verify(&key, &sig, &octets).map_err(|x| format!("author signature: {}", x))?;

    // (5) the envelope's `name`, `artifact` and `parent` equal the entry's `name`,
    // `hash` and `prev`, where an empty `prev` corresponds to `-`. Failing this
    // means the store recorded a transition its author did not sign, which MUST be
    // a hard failure rather than a warning.
    if env.name != e.name {
        return Err(format!("envelope name {:?} does not equal entry name {:?}", env.name, e.name));
    }
    if env.artifact != e.hash {
        return Err(format!(
            "envelope artifact {} does not equal entry hash {}",
            env.artifact, e.hash
        ));
    }
    let entry_parent = if e.prev.is_empty() { "-" } else { e.prev.as_str() };
    if env.parent_str() != entry_parent {
        return Err(format!(
            "envelope parent {} does not equal entry prev {}",
            env.parent_str(),
            entry_parent
        ));
    }
    Ok(Some(env))
}

// ---------------------------------------------------------------------------
// §8.6.2 — the name revision.
// ---------------------------------------------------------------------------

/// What an entry did to a NAME (§8.6.3). A different dimension from `status`,
/// which records what the store concluded about the ARTIFACT: a definition may be
/// `falsified` and still bind its name, a request may be `rejected` and belong in
/// the journal without moving anything, and a `prove` or `cross` entry concerns an
/// artifact and touches no name.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum NameTransition {
    Applied,
    Unchanged,
    None,
}

impl NameTransition {
    pub fn as_str(self) -> &'static str {
        match self {
            NameTransition::Applied => "applied",
            NameTransition::Unchanged => "unchanged",
            NameTransition::None => "none",
        }
    }
}

/// Parse the `name_transition` member. An unrecognized value is an ERROR, not a
/// silent "none": treating it as "none" would under-count the revision, and an
/// under-counted revision re-opens exactly the replay window §8.6.2 exists to
/// close. Fail closed.
fn explicit_transition(v: &str) -> Result<NameTransition, String> {
    match v {
        "applied" => Ok(NameTransition::Applied),
        "unchanged" => Ok(NameTransition::Unchanged),
        "none" => Ok(NameTransition::None),
        other => Err(format!(
            "name_transition {:?} is none of applied/unchanged/none",
            other
        )),
    }
}

/// The legacy derivation of §8.6.2, for entries written before `name_transition`
/// existed. `bound` is what the name is bound to AT THIS POINT IN THE LOG — the
/// running value of the fold, which is why this takes it as an argument.
///
/// §8.6.2 is explicit that an implementation MUST NOT extend this derivation to
/// entries that carry the member, so the caller checks for the member first.
///
/// The KIND restriction comes first and is easy to miss: a `prove` (§8.5) or
/// `cross` entry concerns an ARTIFACT and touches no name, so counting it would
/// inflate a name's revision. `kind` ABSENT is eligible, which the "(nor absent)"
/// parenthetical says and which matters for the oldest entries of all.
pub fn derive_legacy_transition(e: &Entry, bound: Option<&str>) -> NameTransition {
    let eligible = e.kind.is_empty() || e.kind == "data" || e.kind == "func";
    if !eligible {
        return NameTransition::None;
    }
    if e.status != "accepted" && e.status != "falsified" {
        return NameTransition::None;
    }
    if bound == Some(e.hash.as_str()) {
        NameTransition::Unchanged
    } else {
        NameTransition::Applied
    }
}

/// The revision fold of §8.6.2.
///
/// "The derivation is a FOLD over the name's entries, not a per-entry predicate.
/// It must track what the name is bound to as it goes, and compare each entry's
/// `hash` against that running value."
///
/// The per-entry alternative — "`prev` equals `hash`, so it was a no-op" — cannot
/// work at all: the rule legacy entries were written under omitted `prev`
/// whenever the name already pointed at the same hash, so a legacy no-op carries
/// NO `prev`, and an absent `prev` is irrecoverably ambiguous between "the name
/// was new" and "the name was already here". That test misses not some no-ops but
/// ALL of them, which turns the revision back into the publication counter
/// §8.6.2 opens by saying it is not.
///
/// `entries` must be in log order. Entries for other names are skipped.
pub fn fold_name(entries: &[Entry], name: &str) -> Result<NameState, String> {
    let mut state = NameState::unpublished(name);
    for e in entries {
        if e.name != name {
            continue;
        }
        let t = if e.name_transition.is_empty() {
            derive_legacy_transition(e, state.bound.as_deref())
        } else {
            explicit_transition(&e.name_transition)?
        };
        if t == NameTransition::Applied {
            state.bound = Some(e.hash.clone());
            state.rev += BigUint::from(1u8);
        }
    }
    Ok(state)
}

/// Every name's state after replaying the journal, keyed by name.
pub fn fold_all(entries: &[Entry]) -> Result<std::collections::BTreeMap<String, NameState>, String> {
    let mut out: std::collections::BTreeMap<String, NameState> = std::collections::BTreeMap::new();
    for e in entries {
        let st = out
            .entry(e.name.clone())
            .or_insert_with(|| NameState::unpublished(&e.name));
        let t = if e.name_transition.is_empty() {
            derive_legacy_transition(e, st.bound.as_deref())
        } else {
            explicit_transition(&e.name_transition)?
        };
        if t == NameTransition::Applied {
            st.bound = Some(e.hash.clone());
            st.rev += BigUint::from(1u8);
        }
    }
    Ok(out)
}

// ---------------------------------------------------------------------------
// Whole-journal verification (§8).
// ---------------------------------------------------------------------------

/// Read and verify a whole journal: strict lines (§8.2.1), `seq` continuity, the
/// chain (§8), entry signatures (§8.4), and signed publications (§8.6.4).
///
/// §8: "A verifier MUST reject a journal containing an unparseable line, a `seq`
/// gap or reorder, an unchained entry after a chained one, or a `chain`
/// mismatch." The one limitation is disclosed rather than papered over: deleting
/// entries from the TAIL leaves a self-consistent file, and an external anchor is
/// required to detect it.
pub fn verify_journal(bytes: &[u8]) -> Result<Vec<Entry>, String> {
    let mut entries = Vec::new();
    let mut anchor: Option<String> = None; // the chain of the most recent chained entry
    let mut prev_seq: Option<BigUint> = None;
    let mut offset = 0usize; // byte offset of the current line's first byte
    let mut lineno = 0usize;

    for line in split_records(bytes)? {
        lineno += 1;
        let e = read_strict(line).map_err(|x| format!("line {}: {}", lineno, x))?;

        if let Some(p) = &prev_seq {
            let want = p + BigUint::from(1u8);
            if e.seq != want {
                return Err(format!(
                    "line {}: seq is {} but the previous entry was {}: a gap or reorder",
                    lineno, e.seq, p
                ));
            }
        }
        prev_seq = Some(e.seq.clone());

        if e.chain.is_empty() {
            if anchor.is_some() {
                return Err(format!("line {}: an unchained entry follows a chained one", lineno));
            }
        } else {
            // The anchor is the chain of the most recent chained entry — or, when
            // no chained entry exists yet (a journal predating this field), the
            // SHA-256 of the entire byte prefix before this entry, which
            // retroactively seals legacy lines.
            let a = match &anchor {
                Some(a) => a.clone(),
                None => sha256_hex(&bytes[..offset]),
            };
            let want = e.chain_over(&a);
            if want != e.chain {
                return Err(format!("line {}: chain mismatch (computed {})", lineno, want));
            }
            anchor = Some(e.chain.clone());
        }

        verify_entry_signature(&e).map_err(|x| format!("line {}: {}", lineno, x))?;
        verify_publication(&e).map_err(|x| format!("line {}: {}", lineno, x))?;

        offset += line.len() + 1;
        entries.push(e);
    }
    Ok(entries)
}

/// Split a journal into records. Each record is LF-terminated; the separator is
/// framing and is not returned, since it is not part of entry identity (§8.2.1).
/// A final record without its LF is an error, not a shorter valid one — `seq` is
/// defined in terms of "newline-terminated log records" (§8.2).
pub fn split_records(bytes: &[u8]) -> Result<Vec<&[u8]>, String> {
    let mut out = Vec::new();
    let mut start = 0usize;
    for (i, b) in bytes.iter().enumerate() {
        if *b == b'\n' {
            out.push(&bytes[start..i]);
            start = i + 1;
        }
    }
    if start != bytes.len() {
        return Err("journal ends with an unterminated record".into());
    }
    Ok(out)
}

/// Append an entry to a journal, computing its `chain` against the existing bytes
/// (§8). Returns the new journal bytes and the appended entry's digest (§8.2.2),
/// which is what an implementation SHOULD return when accepting a publication so
/// a client can verify the exact accepted transition rather than searching for it.
pub fn append(bytes: &[u8], mut e: Entry) -> Result<(Vec<u8>, String), String> {
    let existing = split_records(bytes)?;
    let mut anchor: Option<String> = None;
    for line in &existing {
        let prev = read_strict(line)?;
        if !prev.chain.is_empty() {
            anchor = Some(prev.chain);
        }
    }
    // `seq` is one plus the number of existing newline-terminated log records.
    e.seq = BigUint::from(existing.len() as u64) + BigUint::from(1u8);
    e.chain.clear();
    let a = anchor.unwrap_or_else(|| sha256_hex(bytes));
    e.chain = e.chain_over(&a);
    let line = e.encode();
    let digest = sha256_hex(&line);
    let mut out = bytes.to_vec();
    out.extend_from_slice(&line);
    out.push(b'\n');
    Ok((out, digest))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn base() -> Entry {
        Entry {
            seq: BigUint::from(1u8),
            time: "2026-07-30T12:00:00Z".into(),
            author: "claude-main".into(),
            verifier: "oathrs/0.1".into(),
            name: "double".into(),
            status: "accepted".into(),
            ..Entry::default()
        }
    }

    #[test]
    fn member_order_is_the_normative_one() {
        // Spelled out literally so a reordering is a test failure and not a
        // silent byte-level fork.
        assert_eq!(
            MEMBER_ORDER.join(","),
            "seq,time,author,verifier,name,kind,status,hash,prev,error,guarantee,termination,\
             context,pubkey,sig,envelope_b64,author_pubkey,author_sig,name_transition,chain"
        );
    }

    #[test]
    fn always_present_members_survive_being_empty() {
        let e = Entry::default();
        assert_eq!(
            String::from_utf8(e.encode()).unwrap(),
            "{\"seq\":0,\"time\":\"\",\"author\":\"\",\"verifier\":\"\",\"name\":\"\",\"status\":\"\"}"
        );
        assert_eq!(read_strict(&e.encode()).unwrap(), e);
    }

    #[test]
    fn empty_members_are_omitted_and_present_ones_keep_order() {
        let mut e = base();
        e.kind = "func".into();
        e.hash = "5".repeat(64);
        e.prev = "6".repeat(64);
        e.name_transition = "applied".into();
        let text = String::from_utf8(e.encode()).unwrap();
        assert!(!text.contains("error"));
        assert!(!text.contains("context"));
        assert!(!text.contains("chain"));
        let ai = text.find("\"author\"").unwrap();
        let vi = text.find("\"verifier\"").unwrap();
        let ni = text.find("\"name\"").unwrap();
        let ki = text.find("\"kind\"").unwrap();
        let si = text.find("\"status\"").unwrap();
        let ti = text.find("\"name_transition\"").unwrap();
        assert!(ai < vi && vi < ni && ni < ki && ki < si && si < ti);
        assert_eq!(read_strict(&e.encode()).unwrap(), e);
    }

    #[test]
    fn strict_reading_refuses_every_non_canonical_spelling() {
        let e = base();
        let line = e.encode();
        assert!(read_strict(&line).is_ok());

        let text = String::from_utf8(line).unwrap();
        // added whitespace
        assert!(read_strict(text.replace("{\"seq\"", "{ \"seq\"").as_bytes()).is_err());
        assert!(read_strict(text.replace("\":", "\" :").as_bytes()).is_err());
        // reordered members
        let reordered = "{\"time\":\"2026-07-30T12:00:00Z\",\"seq\":1,\"author\":\"claude-main\",\
                         \"verifier\":\"oathrs/0.1\",\"name\":\"double\",\"status\":\"accepted\"}";
        assert!(parse(reordered.as_bytes()).is_ok(), "it parses...");
        assert!(read_strict(reordered.as_bytes()).is_err(), "...but is not canonical");
        // unknown member
        assert!(read_strict(text.replace("{\"seq\"", "{\"who\":\"x\",\"seq\"").as_bytes()).is_err());
        // duplicated member
        assert!(read_strict(text.replace("\"seq\":1", "\"seq\":1,\"seq\":1").as_bytes()).is_err());
        // trailing content after the object
        assert!(read_strict(format!("{} ", text).as_bytes()).is_err());
        assert!(read_strict(format!("{}{}", text, text).as_bytes()).is_err());
        // an always-present member removed
        assert!(read_strict(text.replace(",\"verifier\":\"oathrs/0.1\"", "").as_bytes()).is_err());
        // a non-canonical seq spelling
        assert!(read_strict(text.replace("\"seq\":1", "\"seq\":01").as_bytes()).is_err());
        assert!(read_strict(text.replace("\"seq\":1", "\"seq\":1.0").as_bytes()).is_err());
        assert!(read_strict(text.replace("\"seq\":1", "\"seq\":\"1\"").as_bytes()).is_err());
    }

    #[test]
    fn html_escaping_is_not_canonical() {
        // §8.2.1: a rejection message containing `<` is enough to fork two
        // implementations, and at least one widely used encoder escapes it.
        let mut e = base();
        e.status = "rejected".into();
        e.error = "type error: <Int> is not <Bool> & that matters / a lot".into();
        let line = e.encode();
        let text = String::from_utf8(line.clone()).unwrap();
        assert!(text.contains("<Int>"), "{}", text);
        assert!(!text.contains("\\u003c"));
        assert!(!text.contains("\\u0026"));
        assert!(!text.contains("\\/"));
        assert_eq!(read_strict(&line).unwrap(), e);
        // The HTML-escaped spelling of the same entry must be refused.
        let escaped = text.replace('<', "\\u003c");
        assert!(read_strict(escaped.as_bytes()).is_err());
    }

    #[test]
    fn unicode_line_terminators_are_escaped_in_entries() {
        let mut e = base();
        e.error = "a\u{2028}b\u{2029}c".into();
        let text = String::from_utf8(e.encode()).unwrap();
        assert!(text.contains("a\\u2028b\\u2029c"), "{}", text);
        assert_eq!(read_strict(&e.encode()).unwrap(), e);
    }

    #[test]
    fn digest_excludes_the_record_separator() {
        let e = base();
        let line = e.encode();
        assert_eq!(e.digest(), crate::hash::sha256_hex(&line));
        let mut with_sep = line.clone();
        with_sep.push(b'\n');
        assert_ne!(e.digest(), crate::hash::sha256_hex(&with_sep));
    }

    #[test]
    fn digest_fixes_position_only_when_chained() {
        let mut e = base();
        assert!(!e.digest_fixes_position());
        let unchained = e.digest();
        // The same content at another position has the same digest while
        // unchained — §8.2.2's narrower guarantee.
        let mut elsewhere = e.clone();
        assert_eq!(elsewhere.digest(), unchained);
        // Once chained, position enters the line and therefore the digest.
        e.chain = e.chain_over("anchor-a");
        elsewhere.chain = elsewhere.chain_over("anchor-b");
        assert!(e.digest_fixes_position());
        assert_ne!(e.digest(), elsewhere.digest());
    }

    #[test]
    fn chain_is_over_the_entry_with_chain_omitted() {
        let mut e = base();
        let c = e.chain_over("anchor");
        e.chain = c.clone();
        // Recomputing from the entry that now carries the chain gives the same
        // value: the field is excluded from its own input.
        assert_eq!(e.chain_over("anchor"), c);
        let mut buf = Vec::from("anchor\n".as_bytes());
        let mut bare = e.clone();
        bare.chain.clear();
        buf.extend_from_slice(&bare.encode());
        assert_eq!(c, crate::hash::sha256_hex(&buf));
    }

    #[test]
    fn entry_signature_covers_authored_fields_only() {
        let secret = crate::ed25519::secret_from_seed(&[3u8; 32]).unwrap();
        let mut e = base();
        e.pubkey = hexs(&secret.public);
        let sig = crate::ed25519::sign(&secret, &e.signed_content());
        e.sig = hexs(&sig);
        assert!(verify_entry_signature(&e).is_ok());

        // Store-assigned fields do not disturb it.
        let mut moved = e.clone();
        moved.seq = BigUint::from(999u32);
        moved.time = "2030-01-01T00:00:00Z".into();
        moved.verifier = "some-other-kernel".into();
        moved.chain = "deadbeef".into();
        assert!(verify_entry_signature(&moved).is_ok());

        // Authored fields do.
        let mut forged = e.clone();
        forged.name = "other".into();
        assert!(verify_entry_signature(&forged).is_err());

        // pubkey without sig, and sig without pubkey, are forged attributions.
        let mut half = e.clone();
        half.sig.clear();
        assert!(verify_entry_signature(&half).is_err());
        let mut half = e.clone();
        half.pubkey.clear();
        assert!(verify_entry_signature(&half).is_err());

        // Neither field: unattributed, no obligation.
        assert!(verify_entry_signature(&base()).is_ok());
    }

    fn hexs(b: &[u8]) -> String {
        let mut s = String::new();
        for x in b {
            s.push(char::from_digit((x >> 4) as u32, 16).unwrap());
            s.push(char::from_digit((x & 0xf) as u32, 16).unwrap());
        }
        s
    }

    fn signed_entry() -> Entry {
        let secret = crate::ed25519::secret_from_seed(&[11u8; 32]).unwrap();
        let author = hexs(&secret.public);
        let env = Envelope {
            name: "double".into(),
            artifact: "5".repeat(64),
            parent: Some("6".repeat(64)),
            parent_rev: BigUint::from(7u8),
            author: author.clone(),
        };
        let octets = env.encode().unwrap();
        let sig = crate::ed25519::sign(&secret, &octets);
        Entry {
            kind: "func".into(),
            hash: "5".repeat(64),
            prev: "6".repeat(64),
            envelope_b64: crate::b64::encode(&octets),
            author_pubkey: author,
            author_sig: hexs(&sig),
            name_transition: "applied".into(),
            ..base()
        }
    }

    #[test]
    fn publication_verification_accepts_an_honest_entry() {
        let e = signed_entry();
        assert!(verify_publication(&e).unwrap().is_some());
        assert_eq!(read_strict(&e.encode()).unwrap(), e);
    }

    #[test]
    fn publication_fields_are_all_or_none() {
        for clear in ["envelope_b64", "author_pubkey", "author_sig"] {
            let mut e = signed_entry();
            e.field_mut(clear).clear();
            let err = verify_publication(&e).unwrap_err();
            assert!(err.contains("all-or-none") || err.contains("partial"), "{}: {}", clear, err);
        }
    }

    #[test]
    fn publication_verification_binds_name_hash_and_prev() {
        // §8.6.4(5): failing this means the store recorded a transition its
        // author did not sign, and it MUST be a hard failure.
        let mut e = signed_entry();
        e.name = "other".into();
        assert!(verify_publication(&e).unwrap_err().contains("envelope name"));

        let mut e = signed_entry();
        e.hash = "9".repeat(64);
        assert!(verify_publication(&e).unwrap_err().contains("envelope artifact"));

        let mut e = signed_entry();
        e.prev = "9".repeat(64);
        assert!(verify_publication(&e).unwrap_err().contains("envelope parent"));

        // An empty `prev` corresponds to `-`, so a first-publication envelope
        // matches an entry with no prev and mismatches one that has it.
        let secret = crate::ed25519::secret_from_seed(&[12u8; 32]).unwrap();
        let author = hexs(&secret.public);
        let env = Envelope {
            name: "double".into(),
            artifact: "5".repeat(64),
            parent: None,
            parent_rev: BigUint::from(0u8),
            author: author.clone(),
        };
        let octets = env.encode().unwrap();
        let mut e = Entry {
            kind: "func".into(),
            hash: "5".repeat(64),
            envelope_b64: crate::b64::encode(&octets),
            author_pubkey: author,
            author_sig: hexs(&crate::ed25519::sign(&secret, &octets)),
            name_transition: "applied".into(),
            ..base()
        };
        assert!(verify_publication(&e).unwrap().is_some());
        e.prev = "6".repeat(64);
        assert!(verify_publication(&e).is_err());
    }

    #[test]
    fn author_must_equal_author_pubkey() {
        let secret = crate::ed25519::secret_from_seed(&[13u8; 32]).unwrap();
        let other = crate::ed25519::secret_from_seed(&[14u8; 32]).unwrap();
        let env = Envelope {
            name: "double".into(),
            artifact: "5".repeat(64),
            parent: Some("6".repeat(64)),
            parent_rev: BigUint::from(7u8),
            author: hexs(&secret.public),
        };
        let octets = env.encode().unwrap();
        let e = Entry {
            kind: "func".into(),
            hash: "5".repeat(64),
            prev: "6".repeat(64),
            envelope_b64: crate::b64::encode(&octets),
            author_pubkey: hexs(&other.public),
            author_sig: hexs(&crate::ed25519::sign(&secret, &octets)),
            ..base()
        };
        assert!(verify_publication(&e).unwrap_err().contains("does not equal author_pubkey"));
    }

    #[test]
    fn envelope_b64_must_be_the_canonical_spelling() {
        let mut e = signed_entry();
        // Unpadded: decodes to the same octets, MUST still be refused.
        e.envelope_b64 = e.envelope_b64.trim_end_matches('=').to_string();
        assert!(verify_publication(&e).is_err());

        let mut e = signed_entry();
        e.envelope_b64 = format!(" {}", e.envelope_b64);
        assert!(verify_publication(&e).is_err());

        // Line-wrapped, as several base64 encoders emit by default.
        let mut e = signed_entry();
        let b = e.envelope_b64.clone();
        e.envelope_b64 = format!("{}\n{}", &b[..8], &b[8..]);
        assert!(verify_publication(&e).is_err());
    }

    // ---- §8.6.2, the revision fold ----------------------------------------

    fn ent(name: &str, kind: &str, status: &str, hash: &str, transition: &str) -> Entry {
        Entry {
            name: name.into(),
            kind: kind.into(),
            status: status.into(),
            hash: hash.into(),
            name_transition: transition.into(),
            ..Entry::default()
        }
    }

    #[test]
    fn explicit_transitions_are_authoritative() {
        // §8.6.2: an entry has applied a transition if and only if
        // `name_transition` is `applied`, and this MUST NOT be inferred from
        // status, kind, prev or artifact equality for any entry carrying it.
        // Here `status` and `kind` say "this bound a name" and the member says it
        // did not: the member wins.
        let entries = vec![
            ent("d", "func", "accepted", "a", "applied"),
            ent("d", "func", "accepted", "b", "unchanged"),
            ent("d", "func", "accepted", "c", "none"),
        ];
        let st = fold_name(&entries, "d").unwrap();
        assert_eq!(st.rev, BigUint::from(1u8));
        assert_eq!(st.bound.as_deref(), Some("a"));
    }

    #[test]
    fn a_no_op_republication_does_not_advance_the_revision() {
        // A → A is `unchanged`: "If it advanced the revision, a harmless no-op
        // would invalidate every envelope prepared against a state that never
        // changed."
        let entries = vec![
            ent("d", "func", "accepted", "a", ""),
            ent("d", "func", "accepted", "a", ""),
            ent("d", "func", "accepted", "a", ""),
        ];
        let st = fold_name(&entries, "d").unwrap();
        assert_eq!(st.rev, BigUint::from(1u8));
        assert_eq!(st.bound.as_deref(), Some("a"));
    }

    #[test]
    fn aba_increments_twice_so_replay_still_fails() {
        // "ABA protection is unaffected: A → B → A increments twice, so an
        // envelope naming the first A carries the wrong revision even though the
        // hash matches again."
        let entries = vec![
            ent("d", "func", "accepted", "a", ""),
            ent("d", "func", "accepted", "b", ""),
            ent("d", "func", "accepted", "a", ""),
        ];
        let st = fold_name(&entries, "d").unwrap();
        assert_eq!(st.rev, BigUint::from(3u8));
        assert_eq!(st.bound.as_deref(), Some("a"));
    }

    #[test]
    fn the_legacy_derivation_is_a_fold_not_a_per_entry_predicate() {
        // Every one of these legacy no-ops carries NO `prev`, which is exactly
        // the case the withdrawn per-entry test ("prev == hash") misses: it would
        // count 5 revisions for 2 distinct states.
        let entries = vec![
            ent("d", "func", "accepted", "a", ""),
            ent("d", "func", "accepted", "a", ""),
            ent("d", "func", "accepted", "a", ""),
            ent("d", "func", "accepted", "b", ""),
            ent("d", "func", "accepted", "b", ""),
        ];
        for e in &entries {
            assert!(e.prev.is_empty(), "legacy no-ops carry no prev");
        }
        assert_eq!(fold_name(&entries, "d").unwrap().rev, BigUint::from(2u8));
    }

    #[test]
    fn legacy_kind_restriction_excludes_artifact_only_entries() {
        // "A `prove` (§8.5) or `cross` entry concerns an ARTIFACT and touches no
        // name, so counting it would inflate a name's revision."
        let entries = vec![
            ent("d", "func", "accepted", "a", ""),
            ent("d", "prove", "accepted", "x", ""),
            ent("d", "cross", "accepted", "y", ""),
            ent("d", "cross", "falsified", "z", ""),
        ];
        let st = fold_name(&entries, "d").unwrap();
        assert_eq!(st.rev, BigUint::from(1u8));
        assert_eq!(st.bound.as_deref(), Some("a"));
        // ...while an ABSENT kind IS eligible ("nor absent").
        let entries = vec![ent("d", "", "accepted", "a", "")];
        assert_eq!(fold_name(&entries, "d").unwrap().rev, BigUint::from(1u8));
    }

    #[test]
    fn legacy_falsified_binds_and_other_statuses_do_not() {
        // "otherwise, `accepted` and `falsified` applied a transition" — a
        // definition may be falsified and still bind its name.
        let entries = vec![ent("d", "func", "falsified", "a", "")];
        assert_eq!(fold_name(&entries, "d").unwrap().rev, BigUint::from(1u8));
        for status in ["rejected", "blocked", "pending"] {
            let entries = vec![ent("d", "func", status, "a", "")];
            let st = fold_name(&entries, "d").unwrap();
            assert_eq!(st.rev, BigUint::from(0u8), "{}", status);
            assert!(st.bound.is_none());
        }
    }

    #[test]
    fn other_names_do_not_move_this_names_revision() {
        let entries = vec![
            ent("d", "func", "accepted", "a", ""),
            ent("e", "func", "accepted", "b", ""),
            ent("e", "func", "accepted", "c", ""),
        ];
        assert_eq!(fold_name(&entries, "d").unwrap().rev, BigUint::from(1u8));
        assert_eq!(fold_name(&entries, "e").unwrap().rev, BigUint::from(2u8));
        let all = fold_all(&entries).unwrap();
        assert_eq!(all["d"].rev, BigUint::from(1u8));
        assert_eq!(all["e"].rev, BigUint::from(2u8));
        assert_eq!(all["e"].bound.as_deref(), Some("c"));
    }

    #[test]
    fn an_unpublished_name_is_parent_dash_rev_zero() {
        let st = fold_name(&[], "never").unwrap();
        assert!(st.bound.is_none());
        assert_eq!(st.rev, BigUint::from(0u8));
    }

    #[test]
    fn an_unrecognized_transition_fails_closed() {
        let entries = vec![ent("d", "func", "accepted", "a", "APPLIED")];
        assert!(fold_name(&entries, "d").is_err());
    }

    #[test]
    fn a_mixed_journal_does_not_apply_the_legacy_rule_to_modern_entries() {
        // §8.6.2: an implementation MUST NOT extend the legacy derivation to
        // entries that carry the member. Entry 2 would be `applied` under the
        // legacy rule (accepted, func, hash differs) but says `none`.
        let entries = vec![
            ent("d", "func", "accepted", "a", ""),
            ent("d", "func", "accepted", "b", "none"),
        ];
        let st = fold_name(&entries, "d").unwrap();
        assert_eq!(st.rev, BigUint::from(1u8));
        assert_eq!(st.bound.as_deref(), Some("a"));
    }

    #[test]
    fn revision_is_monotonic_and_never_reused() {
        // §8.6.2 requires monotonicity per name. Exercised as a property over a
        // long alternating history rather than asserted once.
        let mut entries = Vec::new();
        for i in 0..40 {
            entries.push(ent("d", "func", "accepted", if i % 3 == 0 { "a" } else { "b" }, ""));
        }
        let mut last = BigUint::from(0u8);
        let mut seen = std::collections::BTreeSet::new();
        for n in 1..=entries.len() {
            let r = fold_name(&entries[..n], "d").unwrap().rev;
            assert!(r >= last, "revision went backwards");
            if r > last {
                assert!(seen.insert(r.clone()), "revision reused");
            }
            last = r;
        }
    }

    // ---- whole-journal verification (§8) ----------------------------------

    fn journal(entries: Vec<Entry>) -> Vec<u8> {
        let mut out = Vec::new();
        for e in entries {
            let (next, _) = append(&out, e).unwrap();
            out = next;
        }
        out
    }

    #[test]
    fn a_chained_journal_verifies_and_a_tampered_one_does_not() {
        let bytes = journal(vec![base(), base(), signed_entry()]);
        let read = verify_journal(&bytes).unwrap();
        assert_eq!(read.len(), 3);
        assert_eq!(read[0].seq, BigUint::from(1u8));
        assert_eq!(read[2].seq, BigUint::from(3u8));

        let text = String::from_utf8(bytes.clone()).unwrap();
        let tampered = text.replacen("claude-main", "someone-else", 1);
        assert!(verify_journal(tampered.as_bytes()).is_err());
    }

    #[test]
    fn seq_gaps_reorders_and_unterminated_records_are_rejected() {
        let bytes = journal(vec![base(), base(), base()]);
        let text = String::from_utf8(bytes.clone()).unwrap();
        // Drop the middle record: seq 1 then 3.
        let lines: Vec<&str> = text.trim_end().split('\n').collect();
        let gapped = format!("{}\n{}\n", lines[0], lines[2]);
        assert!(verify_journal(gapped.as_bytes()).unwrap_err().contains("gap or reorder"));
        // Reorder.
        let reordered = format!("{}\n{}\n{}\n", lines[1], lines[0], lines[2]);
        assert!(verify_journal(reordered.as_bytes()).is_err());
        // Unterminated final record.
        assert!(verify_journal(text.trim_end().as_bytes()).is_err());
    }

    #[test]
    fn an_unchained_entry_after_a_chained_one_is_rejected() {
        let bytes = journal(vec![base(), base()]);
        let mut third = base();
        third.seq = BigUint::from(3u8);
        let mut with = bytes.clone();
        with.extend_from_slice(&third.encode());
        with.push(b'\n');
        assert!(verify_journal(&with).unwrap_err().contains("unchained entry follows"));
    }

    #[test]
    fn a_legacy_prefix_is_retroactively_sealed_by_the_first_chain() {
        // "when no chained entry exists yet (a journal predating this field), the
        // SHA-256 of the entire byte prefix before this entry, which
        // retroactively seals legacy lines."
        let mut legacy = Vec::new();
        for i in 1..=2u32 {
            let mut e = base();
            e.seq = BigUint::from(i);
            legacy.extend_from_slice(&e.encode());
            legacy.push(b'\n');
        }
        let (with_chain, digest) = append(&legacy, base()).unwrap();
        assert_eq!(verify_journal(&with_chain).unwrap().len(), 3);
        assert_eq!(digest.len(), 64);

        // Altering a legacy line invalidates the later chain.
        let text = String::from_utf8(with_chain).unwrap();
        let tampered = text.replacen("\"double\"", "\"doubl3\"", 1);
        assert!(verify_journal(tampered.as_bytes()).is_err());
    }

    #[test]
    fn append_returns_the_entry_digest_of_the_line_it_wrote() {
        let (bytes, digest) = append(b"", base()).unwrap();
        let line = &bytes[..bytes.len() - 1];
        assert_eq!(digest, crate::hash::sha256_hex(line));
        assert_eq!(read_strict(line).unwrap().digest(), digest);
    }
}

