//!     Checked in both directions — encode to the fixture bytes, and parse the
//!     fixture bytes back to the same envelope.
//!   * `reject` — octets (or a stored `envelope_b64` member) that MUST be refused.
//!   * `signature` — the whole path, with a `verdict`; tamper records carry
//!     `tampered_field` and MUST fail, since "a signed field that still verifies
//!     after tampering is not bound by the signature".
//!   * `store` — a `state` plus a `request`, witnessing §8.6.4's three store-side
//!     MUSTs. Half of §8.6's normative weight is store-side.
//!
//! Nothing here touches identity; like `read_outcomes`, it is CLI plumbing for
//! the fixture channel and therefore lives in the binary, not the kernel library.

use num_bigint::BigUint;
use oathrs::b64;
use oathrs::ed25519;
use oathrs::envelope::{self, Envelope, NameState, PublishRequest};
use oathrs::journal;
use oathrs::json::{self, Json};

pub struct Report {
    pub counts: std::collections::BTreeMap<String, usize>,
    pub failures: Vec<String>,
}

fn hexs(bytes: &[u8]) -> String {
    let mut s = String::with_capacity(bytes.len() * 2);
    for b in bytes {
        s.push(char::from_digit((b >> 4) as u32, 16).unwrap());
        s.push(char::from_digit((b & 0xf) as u32, 16).unwrap());
    }
    s
}

fn field<'a>(o: &'a Json, key: &str) -> Result<&'a Json, String> {
    o.get(key).ok_or_else(|| format!("record has no {:?}", key))
}

fn text(o: &Json, key: &str) -> Result<String, String> {
    field(o, key)?
        .str()
        .map(|s| s.to_string())
        .ok_or_else(|| format!("{:?} is not a string", key))
}

fn opt_text(o: &Json, key: &str) -> Option<String> {
    o.get(key).and_then(|v| v.str()).map(|s| s.to_string())
}

fn octets(o: &Json, key: &str) -> Result<Vec<u8>, String> {
    b64::decode_canonical(&text(o, key)?).map_err(|e| format!("{}: {}", key, e))
}

/// Read a non-negative integer that the fixture may carry either as a JSON number
/// or as a JSON string. Both spellings appear in this one file — `envelope`
/// objects use a number, `store` states use a string — and neither may be widened
/// to a machine word, since §8.6.1 declares `parent_rev` unbounded and one vector
/// carries a value past 2^64.
fn big(o: &Json, key: &str) -> Result<BigUint, String> {
    let v = field(o, key)?;
    let digits = match v {
        Json::Num(n) => n.clone(),
        Json::Str(s) => s.clone(),
        _ => return Err(format!("{:?} is neither a number nor a string", key)),
    };
    if digits.is_empty() || !digits.bytes().all(|c| c.is_ascii_digit()) {
        return Err(format!("{:?} = {:?} is not a non-negative decimal integer", key, digits));
    }
    BigUint::parse_bytes(digits.as_bytes(), 10)
        .ok_or_else(|| format!("{:?} = {:?} does not parse", key, digits))
}

/// Rebuild an `Envelope` from a fixture's structured `envelope` object.
fn envelope_of(o: &Json) -> Result<Envelope, String> {
    let op = text(o, "op")?;
    if op != "put" {
        return Err(format!("structured envelope has op {:?}, want \"put\"", op));
    }
    let parent_text = text(o, "parent")?;
    Ok(Envelope {
        name: text(o, "name")?,
        artifact: text(o, "artifact")?,
        parent: if parent_text == "-" { None } else { Some(parent_text) },
        parent_rev: big(o, "parent_rev")?,
        author: text(o, "author")?,
    })
}

fn where_differ(a: &[u8], b: &[u8]) -> String {
    for i in 0..a.len().min(b.len()) {
        if a[i] != b[i] {
            return format!("first difference at byte {} (got 0x{:02x}, want 0x{:02x})", i, a[i], b[i]);
        }
    }
    format!("lengths differ: got {}, want {}", a.len(), b.len())
}

/// A `signature` record's verification path: §8.6.4 clauses (2), (3) and (4) over
/// the octets as stored. Clause (5) needs a journal entry and is checked
/// separately for the record that carries one.
fn verify_signature_record(
    octets: &[u8],
    author_pubkey: &str,
    author_sig: &str,
) -> Result<Envelope, String> {
    let env = envelope::parse_canonical(octets)?;
    if env.author != author_pubkey {
        return Err(format!(
            "envelope author {} does not equal author_pubkey {}",
            env.author, author_pubkey
        ));
    }
    let key = envelope::unhex(author_pubkey).map_err(|e| format!("author_pubkey: {}", e))?;
    let sig = envelope::unhex(author_sig).map_err(|e| format!("author_sig: {}", e))?;
    ed25519::verify(&key, &sig, octets).map_err(|e| format!("author signature: {}", e))?;
    Ok(env)
}

fn check_canonical(o: &Json) -> Result<(), String> {
    let env = envelope_of(field(o, "envelope")?)?;
    let want = octets(o, "octets_b64")?;
    let got = env.encode()?;
    if got != want {
        return Err(format!(
            "encoded octets differ from the fixture: {}\n      got:  {:?}\n      want: {:?}",
            where_differ(&got, &want),
            String::from_utf8_lossy(&got),
            String::from_utf8_lossy(&want)
        ));
    }
    // The other direction: the fixture bytes must parse back to the same
    // envelope, and re-encode to themselves (§8.6.1's parse obligation).
    let back = envelope::parse_canonical(&want)?;
    if back != env {
        return Err(format!("fixture octets parse to {:?}, not the structured envelope", back));
    }
    Ok(())
}

fn check_reject(o: &Json) -> Result<(), String> {
    // Two shapes: raw octets that must not parse, or a stored `envelope_b64`
    // member that must not be accepted by a verifier.
    if let Some(m) = opt_text(o, "envelope_b64") {
        // The member goes through the §8.6.3 dialect check and then §8.6.1.
        let res = b64::decode_canonical(&m).and_then(|oct| {
            envelope::parse_canonical(&oct).map(|_| ()).map_err(|e| e)
        });
        return match res {
            Ok(()) => Err("envelope_b64 member was ACCEPTED but MUST be refused".into()),
            Err(_) => Ok(()),
        };
    }
    let oct = octets(o, "octets_b64")?;
    match envelope::parse_canonical(&oct) {
        Ok(env) => Err(format!("octets were ACCEPTED but MUST be refused (parsed to {:?})", env)),
        Err(_) => Ok(()),
    }
}

fn check_signature(o: &Json) -> Result<(), String> {
    let verdict = text(o, "verdict")?;
    let oct = octets(o, "octets_b64")?;
    let pubkey = text(o, "author_pubkey")?;
    let sig = text(o, "author_sig")?;
    let result = verify_signature_record(&oct, &pubkey, &sig);

    match (verdict.as_str(), &result) {
        ("accept", Err(e)) => return Err(format!("MUST verify but did not: {}", e)),
        ("reject", Ok(_)) => {
            return Err(format!(
                "MUST fail verification but verified{}",
                match opt_text(o, "tampered_field") {
                    Some(f) => format!(" (tampered field {:?} is therefore not bound by the signature)", f),
                    None => String::new(),
                }
            ))
        }
        ("accept", Ok(_)) | ("reject", Err(_)) => {}
        (v, _) => return Err(format!("unknown verdict {:?}", v)),
    }
    if verdict != "accept" {
        return Ok(());
    }

    // An accepting record carries the rest of the path, and each piece is a
    // separate normative obligation.
    if let Some(e) = o.get("envelope") {
        let env = envelope_of(e)?;
        if env.encode()? != oct {
            return Err("structured envelope does not encode to octets_b64".into());
        }
    }
    if let Some(stored) = opt_text(o, "envelope_b64") {
        // §8.6.3: the octets are recoverable as the DECODED value of this member,
        // in the pinned dialect and in no other spelling.
        if b64::encode(&oct) != stored {
            return Err("envelope_b64 is not the canonical base64 of the octets".into());
        }
        if b64::decode_canonical(&stored)? != oct {
            return Err("envelope_b64 does not decode to the octets".into());
        }
    }
    // §8.6.4a: signing is deterministic, so the fixture pins a seed rather than a
    // nonce — and a kernel that cannot re-derive the key and the signature from
    // that seed cannot use the fixture at all.
    if let Some(seed_b64) = opt_text(o, "seed_b64") {
        let seed = b64::decode_canonical(&seed_b64)?;
        let secret = ed25519::secret_from_seed(&seed)?;
        if hexs(&secret.public) != pubkey {
            return Err(format!(
                "seed derives public key {}, not author_pubkey {}",
                hexs(&secret.public),
                pubkey
            ));
        }
        if hexs(&ed25519::sign(&secret, &oct)) != sig {
            return Err("deterministic signing over the octets does not reproduce author_sig".into());
        }
    }
    // The journal side: §8.2.1 strict reading, then all five §8.6.4 clauses.
    if let Some(line_b64) = opt_text(o, "journal_line_b64") {
        let line = b64::decode_canonical(&line_b64)?;
        let entry = journal::read_strict(&line)
            .map_err(|e| format!("journal line is not canonical (§8.2.1): {}", e))?;
        journal::verify_publication(&entry)
            .map_err(|e| format!("journal entry publication check (§8.6.4): {}", e))?
            .ok_or("journal entry carries no publication fields")?;
        if entry.envelope_b64 != b64::encode(&oct) {
            return Err("journal entry's envelope_b64 is not the record's octets".into());
        }
        // §8.2.2: the entry digest is the identity of this publication. This line
        // is UNCHAINED, so the digest identifies content only and does NOT fix
        // position — the narrower guarantee, which an implementation relying on
        // positional uniqueness must not assume.
        let digest = entry.digest();
        if digest.len() != 64 || !digest.bytes().all(|c| c.is_ascii_digit() || (b'a'..=b'f').contains(&c)) {
            return Err(format!("entry digest {:?} is not lowercase hex", digest));
        }
        if entry.digest_fixes_position() {
            return Err("the fixture's journal line is unchained, so its digest must not be treated as fixing position".into());
        }
    }
    Ok(())
}

fn check_store(o: &Json) -> Result<(), String> {
    let verdict = text(o, "verdict")?;
    let st = field(o, "state")?;
    let bound = opt_text(st, "bound").filter(|s| !s.is_empty() && s != "-");
    let state = NameState { name: text(st, "name")?, bound, rev: big(st, "parent_rev")? };
    let rq = field(o, "request")?;
    let req = PublishRequest {
        octets: octets(rq, "octets_b64")?,
        author_sig: text(rq, "author_sig")?,
        authenticated_principal: text(rq, "authenticated_principal")?,
        recomputed_artifact: text(rq, "recomputed_artifact")?,
    };
    match (verdict.as_str(), envelope::check_publication(&state, &req)) {
        ("accept", Err(e)) => Err(format!("store MUST accept but refused: {}", e)),
        ("reject", Ok(_)) => Err("store MUST refuse but accepted: the name would move".into()),
        ("accept", Ok(_)) | ("reject", Err(_)) => Ok(()),
        (v, _) => Err(format!("unknown verdict {:?}", v)),
    }
}

/// Run every record. Returns the per-kind counts and one message per failure.
pub fn run(path: &str) -> Result<Report, String> {
    let bytes = std::fs::read(path).map_err(|e| format!("reading {}: {}", path, e))?;
    let mut counts: std::collections::BTreeMap<String, usize> = std::collections::BTreeMap::new();
    let mut failures = Vec::new();
    for (i, line) in bytes.split(|&b| b == b'\n').enumerate() {
        if line.is_empty() {
            continue;
        }
        let lineno = i + 1;
        let o = match json::parse(line) {
            Ok(v) => v,
            Err(e) => {
                failures.push(format!("line {}: unparseable record: {}", lineno, e));
                continue;
            }
        };
        let kind = match o.get("kind").and_then(|v| v.str()) {
            Some(k) => k.to_string(),
            None => {
                failures.push(format!("line {}: record has no kind", lineno));
                continue;
            }
        };
        let label = opt_text(&o, "label").unwrap_or_else(|| "(unlabelled)".into());
        let res = match kind.as_str() {
            "canonical" => check_canonical(&o),
            "reject" => check_reject(&o),
            "signature" => check_signature(&o),
            "store" => check_store(&o),
            other => Err(format!("unknown record kind {:?}", other)),
        };
        *counts.entry(kind.clone()).or_insert(0) += 1;
        if let Err(e) = res {
            failures.push(format!("line {} [{}] {}: {}", lineno, kind, label, e));
        }
    }
    if counts.is_empty() {
        return Err(format!("{} contained no records", path));
    }
    Ok(Report { counts, failures })
}

