/// Run the §10.1 signed-publication vectors (SPEC §8.6). Every record kind is
/// exercised: `canonical` octets must reproduce byte-for-byte, `reject` records
/// must be refused, and `signature` and `store` records must accept or fail
/// exactly as their `verdict` says.
fn cmd_envelope(path: &str) -> i32 {
    let report = match vectors::run(path) {
        Ok(r) => r,
        Err(e) => {
            eprintln!("error: {}", e);
            return 1;
        }
    };
    let total: usize = report.counts.values().sum();
    let breakdown: Vec<String> =
        report.counts.iter().map(|(k, n)| format!("{} {}", n, k)).collect();
    if report.failures.is_empty() {
        println!("{} envelope vectors OK ({})", total, breakdown.join(", "));
        0
    } else {
        for f in &report.failures {
            println!("FAIL {}", f);
        }
        println!(
            "{} of {} envelope vectors failed ({})",
            report.failures.len(),
            total,
            breakdown.join(", ")
        );
        1
    }
}

