// The small-order rule is the ONLY thing standing between the identity key
// and a universal forgery, which is what §8.6.4a means by "signatures under
// it verify for parties who do not hold it".
//
// Take A = the identity point. Then [k]A is the identity for every k, so the
// cofactorless equation [S]B = R + [k]A reduces to [S]B = R, and S = 0 with
// R = the identity encoding satisfies it for ANY message — with no private
// key involved at all. A verifier that checks only the equation ACCEPTS this
// as a valid authorship claim over arbitrary octets.
#[test]
fn identity_key_yields_a_universal_forgery_that_only_the_small_order_rule_stops() {
    let c = Curve::new();
    let a_enc = c.encode_point(&c.identity());
    let mut sig = [0u8; 64];
    sig[..32].copy_from_slice(&a_enc); // R = the identity point
    // S = 0, already zeroed.

    for msg in [b"oath-publish/1\n".as_slice(), b"".as_slice(), b"anything at all".as_slice()] {
        // The equation itself holds — this is a genuine solution, not a near miss.
        let a = c.decode_point(&a_enc).unwrap();
        let r = c.decode_point(&sig[..32]).unwrap();
        let mut buf = Vec::new();
        buf.extend_from_slice(&sig[..32]);
        buf.extend_from_slice(&a_enc);
        buf.extend_from_slice(msg);
        let k = BigUint::from_bytes_le(&sha512(&buf)) % &c.l;
        let s = BigUint::from_bytes_le(&sig[32..]);
        assert!(s < c.l, "S is canonical, so the S rule does not catch it");
        assert!(
            c.eq(&c.mul(&s, &c.b), &c.add(&r, &c.mul(&k, &a))),
            "[S]B == R + [k]A holds for the identity key"
        );
        // ...and it is refused anyway, by the small-order rule alone.
        let e = verify(&a_enc, &sig, msg).unwrap_err();
        assert!(e.contains("small-order"), "{}", e);
    }
}

// A genuine key is NOT small order, so the rule costs nothing legitimate.

